// `@bufbuild/protobuf` v2 (`protoc-gen-es`) exact symbol & member naming
// ---------------------------------------------------------------------------

/// Reserved ECMAScript/TypeScript top-level identifiers salted with `$` by `@bufbuild/protoplugin`.
const ES_RESERVED_IDENTIFIERS: &[&str] = &[
    "Object",
    "Partial",
    "Uint8Array",
    "bigint",
    "boolean",
    "break",
    "case",
    "catch",
    "class",
    "const",
    "continue",
    "debugger",
    "default",
    "delete",
    "do",
    "else",
    "enum",
    "export",
    "extends",
    "false",
    "finally",
    "for",
    "function",
    "globalThis",
    "if",
    "implements",
    "import",
    "in",
    "instanceof",
    "interface",
    "let",
    "new",
    "null",
    "number",
    "object",
    "package",
    "private",
    "protected",
    "public",
    "return",
    "static",
    "string",
    "super",
    "switch",
    "this",
    "throw",
    "true",
    "try",
    "typeof",
    "var",
    "void",
    "while",
    "with",
    "yield",
];

fn es_safe_identifier(name: &str) -> String {
    if ES_RESERVED_IDENTIFIERS.binary_search(&name).is_ok() {
        format!("{name}$")
    } else {
        name.to_string()
    }
}

fn es_safe_object_property(name: &str) -> String {
    if matches!(name, "constructor" | "toString" | "toJSON" | "valueOf") {
        format!("{name}$")
    } else {
        name.to_string()
    }
}

/// Exact port of `@bufbuild/protobuf`'s `protoCamelCase`.
fn es_proto_camel_case(snake_case: &str) -> String {
    let mut cap_next = false;
    let mut out = String::with_capacity(snake_case.len());
    for ch in snake_case.chars() {
        match ch {
            '_' => cap_next = true,
            '0'..='9' => {
                out.push(ch);
                cap_next = false;
            }
            other => {
                if cap_next {
                    cap_next = false;
                    out.push(other.to_ascii_uppercase());
                } else {
                    out.push(other);
                }
            }
        }
    }
    out
}

/// Exact port of `@bufbuild/protobuf`'s `camelToSnakeCase` (used for enum shared-prefix stripping).
fn es_camel_to_snake_case(camel: &str) -> String {
    let mut out = String::with_capacity(camel.len() + 4);
    for (idx, ch) in camel.chars().enumerate() {
        if idx > 0 && ch.is_ascii_uppercase() {
            out.push('_');
        }
        out.push(ch.to_ascii_lowercase());
    }
    out
}

fn es_field_local_name(wit_name: &str) -> String {
    es_safe_object_property(&es_proto_camel_case(&ident::proto_field_name(wit_name)))
}

fn es_oneof_case_local_name(wit_name: &str) -> String {
    es_proto_camel_case(&ident::proto_field_name(wit_name))
}

fn es_find_enum_shared_prefix(enum_name: &str, values: &[String]) -> Option<String> {
    let prefix = format!("{}_", es_camel_to_snake_case(enum_name));
    for value in values {
        if !value.to_ascii_lowercase().starts_with(&prefix) {
            return None;
        }
        let short = &value[prefix.len()..];
        if short.is_empty() || short.as_bytes()[0].is_ascii_digit() {
            return None;
        }
    }
    Some(prefix)
}

/// Exact `@bufbuild/protobuf` v2 exported type, `*Schema` descriptor, and enum member names for
/// one emitted `.proto` file, reproducing `@bufbuild/protoplugin`'s `allNames` pass.
#[derive(Debug, Clone)]
struct EsFileNames {
    shapes: BTreeMap<String, String>,
    descs: BTreeMap<String, String>,
    enum_members: BTreeMap<String, BTreeMap<String, String>>,
}

impl EsFileNames {
    fn parse(file_name: &str, proto_src: &str) -> Self {
        let mut messages: Vec<String> = Vec::new();
        let mut enums: Vec<(String, Vec<String>)> = Vec::new();
        let mut depth: usize = 0;
        let mut current_enum: Option<usize> = None;

        for raw_line in proto_src.lines() {
            let line = raw_line.trim();
            if line.is_empty() || line.starts_with("//") {
                continue;
            }
            if depth == 0 {
                if let Some(rest) = line.strip_prefix("message ")
                    && let Some(name) = rest.split_whitespace().next()
                {
                    let name = name.trim_end_matches('{');
                    if !name.is_empty() {
                        messages.push(name.to_string());
                    }
                } else if let Some(rest) = line.strip_prefix("enum ")
                    && let Some(name) = rest.split_whitespace().next()
                {
                    let name = name.trim_end_matches('{');
                    if !name.is_empty() {
                        enums.push((name.to_string(), Vec::new()));
                        current_enum = Some(enums.len() - 1);
                    }
                }
            } else if depth == 1
                && let Some(enum_idx) = current_enum
                && !line.starts_with("option ")
                && !line.starts_with("reserved ")
                && !line.starts_with('}')
                && let Some((lhs, _)) = line.split_once('=')
            {
                let val_name = lhs.trim();
                if !val_name.is_empty() {
                    enums[enum_idx].1.push(val_name.to_string());
                }
            }

            for ch in line.chars() {
                if ch == '{' {
                    depth += 1;
                } else if ch == '}' {
                    depth = depth.saturating_sub(1);
                    if depth == 0 {
                        current_enum = None;
                    }
                }
            }
        }

        let mut taken: BTreeSet<String> = BTreeSet::new();
        let mut shapes: BTreeMap<String, String> = BTreeMap::new();
        let mut descs: BTreeMap<String, String> = BTreeMap::new();

        // Pass 1: shape names (messages, then enums), matching `nestedTypes(file)`.
        for name in messages
            .iter()
            .chain(enums.iter().map(|(enum_name, _)| enum_name))
        {
            let allocated = allocate_es_name(&mut taken, name, "");
            shapes.insert(name.clone(), allocated);
        }

        // Pass 2: file descriptor, then message schemas, then enum schemas.
        let file_stem = file_name.strip_suffix(".proto").unwrap_or(file_name);
        let mut file_desc_base = String::from("file_");
        let mut prev_sep = false;
        for ch in file_stem.chars() {
            if ch.is_ascii_alphanumeric() || ch == '_' {
                file_desc_base.push(ch);
                prev_sep = false;
            } else if !prev_sep {
                file_desc_base.push('_');
                prev_sep = true;
            }
        }
        let _ = allocate_es_name(&mut taken, &file_desc_base, "");

        for name in messages
            .iter()
            .chain(enums.iter().map(|(enum_name, _)| enum_name))
        {
            let allocated = allocate_es_name(&mut taken, name, "Schema");
            descs.insert(name.clone(), allocated);
        }

        // Enum value local names (with shared prefix stripping).
        let mut enum_members: BTreeMap<String, BTreeMap<String, String>> = BTreeMap::new();
        for (enum_name, values) in enums {
            let shared = es_find_enum_shared_prefix(&enum_name, &values);
            let mut map = BTreeMap::new();
            for val in values {
                let local = match &shared {
                    Some(prefix) => &val[prefix.len()..],
                    None => val.as_str(),
                };
                map.insert(val.clone(), es_safe_object_property(local));
            }
            enum_members.insert(enum_name, map);
        }

        Self {
            shapes,
            descs,
            enum_members,
        }
    }

    fn shape(&self, proto_name: &str) -> String {
        self.shapes
            .get(proto_name)
            .cloned()
            .unwrap_or_else(|| es_safe_identifier(proto_name))
    }

    fn desc(&self, proto_name: &str) -> String {
        self.descs
            .get(proto_name)
            .cloned()
            .unwrap_or_else(|| es_safe_identifier(&format!("{proto_name}Schema")))
    }

    fn enum_member(&self, proto_enum: &str, proto_value: &str) -> String {
        self.enum_members
            .get(proto_enum)
            .and_then(|map| map.get(proto_value))
            .cloned()
            .unwrap_or_else(|| es_safe_object_property(proto_value))
    }
}

fn allocate_es_name(taken: &mut BTreeSet<String>, base: &str, suffix: &str) -> String {
    for idx in 0usize.. {
        let salt = match idx {
            0 => String::new(),
            1 => "$".to_string(),
            n => format!("${}", n - 1),
        };
        let candidate = es_safe_identifier(&format!("{base}{suffix}{salt}"));
        if taken.insert(candidate.clone()) {
            return candidate;
        }
    }
    unreachable!("infinite salt iterator always terminates")
}

// ---------------------------------------------------------------------------
// Package & interface glue emitter
// ---------------------------------------------------------------------------

struct PackageEmitContext<'a> {
    header: &'a str,
    model: &'a Model,
    lock: &'a WireLock,
    plain_root: &'a str,
    proto_root: &'a str,
    root_major: u64,
    plain_pkg_rel: String,
    proto_file_stem: String,
    file_depth: usize,
    dep_layout: &'a DepLayout,
    es_files: &'a BTreeMap<String, EsFileNames>,
    es_names: &'a EsFileNames,
    dep_context: Option<&'a Dependency>,
    dep_scoped: bool,
}

fn plan_interface_names<'a>(
    interfaces: &'a [Interface],
    scope: &str,
) -> Result<Vec<(&'a Interface, String, String)>> {
    let mut stems: BTreeMap<String, String> = BTreeMap::new();
    let mut idents: BTreeMap<String, String> = BTreeMap::new();
    let mut planned = Vec::with_capacity(interfaces.len());

    for interface in interfaces {
        let stem = safe_interface_file_stem(&interface.name)?;
        let stem_lower = stem.to_ascii_lowercase();
        if let Some(previous) = stems.insert(stem_lower, interface.name.clone()) {
            contract_bail!(
                "{scope}: interfaces `{previous}` and `{}` both map to TypeScript glue file \
                 `{stem}.ts`",
                interface.name
            );
        }
        let export_ident = ts_value_ident(&interface.name, "interface namespace")?;
        if let Some(previous) = idents.insert(export_ident.clone(), interface.name.clone()) {
            contract_bail!(
                "{scope}: interfaces `{previous}` and `{}` both map to TypeScript glue namespace \
                 `{export_ident}`",
                interface.name
            );
        }
        planned.push((interface, stem, export_ident));
    }
    Ok(planned)
}

fn emit_package_glue(ctx: &PackageEmitContext<'_>) -> Result<BTreeMap<String, String>> {
    let pkg_label = format!(
        "{}:{}@{}",
        ctx.model.package.namespace, ctx.model.package.name, ctx.model.package.version
    );
    let iface_plan = plan_interface_names(&ctx.model.interfaces, &pkg_label)?;
    let stem_by_name: BTreeMap<&str, &str> = iface_plan
        .iter()
        .map(|(iface, stem, _)| (iface.name.as_str(), stem.as_str()))
        .collect();

    let mut out_files = BTreeMap::new();
    for (interface, stem, _) in &iface_plan {
        let source = emit_interface_glue(ctx, interface, stem, &stem_by_name)?;
        out_files.insert(format!("{stem}.ts"), source);
    }

    let mut barrel = String::new();
    writeln!(barrel, "{}", ctx.header)?;
    writeln!(barrel, "// source: {pkg_label}")?;
    if iface_plan.is_empty() {
        writeln!(barrel)?;
        writeln!(barrel, "export {{}};")?;
    } else {
        for (interface, stem, export_ident) in &iface_plan {
            writeln!(barrel)?;
            let fallback = format!("Checked protobuf glue for interface `{}`.", interface.name);
            write_jsdoc(
                &mut barrel,
                0,
                &interface.docs,
                &interface.stability,
                Some(&fallback),
            )?;
            writeln!(barrel, "export * as {export_ident} from \"./{stem}.js\";")?;
        }
    }
    out_files.insert("index.ts".to_string(), barrel);
    Ok(out_files)
}

#[derive(Default)]
struct GlueImports {
    runtime: BTreeSet<&'static str>,
    plain_shared_values: BTreeSet<&'static str>,
    plain_shared_types: BTreeSet<&'static str>,
    plain_type_imports: BTreeMap<String, String>,
    proto_type_imports: BTreeMap<String, String>,
    glue_value_imports: BTreeMap<String, String>,
    used_aliases: BTreeSet<String>,
}

impl GlueImports {
    fn mark(&mut self, key: &'static str) {
        self.runtime.insert(key);
    }

    fn has(&self, key: &'static str) -> bool {
        self.runtime.contains(key)
    }

    fn use_create(&mut self) {
        self.mark("create");
    }

    fn use_error(&mut self) {
        self.mark("error");
    }

    fn use_helpers(&mut self) {
        self.mark("helpers");
    }

    fn use_local_plain(&mut self) {
        self.mark("local_plain");
    }

    fn use_local_proto_type(&mut self) {
        self.mark("local_proto_type");
    }

    fn use_local_proto_value(&mut self) {
        self.mark("local_proto_value");
    }

    fn use_option_type(&mut self) {
        self.plain_shared_types.insert("Option");
    }

    fn use_none(&mut self) {
        self.plain_shared_values.insert("NONE");
    }

    fn use_some(&mut self) {
        self.plain_shared_values.insert("some");
    }

    fn alias_in(
        map: &mut BTreeMap<String, String>,
        used: &mut BTreeSet<String>,
        specifier: String,
        preferred_base: &str,
    ) -> String {
        if let Some(existing) = map.get(&specifier) {
            return existing.clone();
        }
        let mut candidate = preferred_base.to_string();
        let mut suffix = 2usize;
        while used.contains(&candidate) {
            candidate = format!("{preferred_base}_{suffix}");
            suffix += 1;
        }
        used.insert(candidate.clone());
        map.insert(specifier, candidate.clone());
        candidate
    }

    fn plain_type_alias(&mut self, specifier: String, preferred_base: &str) -> String {
        Self::alias_in(
            &mut self.plain_type_imports,
            &mut self.used_aliases,
            specifier,
            preferred_base,
        )
    }

    fn proto_type_alias(&mut self, specifier: String, preferred_base: &str) -> String {
        Self::alias_in(
            &mut self.proto_type_imports,
            &mut self.used_aliases,
            specifier,
            preferred_base,
        )
    }

    fn glue_value_alias(&mut self, specifier: String, preferred_base: &str) -> String {
        Self::alias_in(
            &mut self.glue_value_imports,
            &mut self.used_aliases,
            specifier,
            preferred_base,
        )
    }
}

struct TempGen {
    next: usize,
}

impl TempGen {
    fn new() -> Self {
        Self { next: 0 }
    }

    fn fresh(&mut self) -> String {
        let name = format!("_v{}", self.next);
        self.next += 1;
        name
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Form {
    Scalar,
    Bytes,
    Enum,
    Message,
    List,
    Map,
    Option,
}

fn qualify_type(dependency: Option<&Dependency>, ty: &TypeExpr) -> TypeExpr {
    let Some(dependency) = dependency else {
        return ty.clone();
    };
    match ty {
        TypeExpr::Named(name) if name.package().is_none() => TypeExpr::Named(QualifiedName {
            interface: format!(
                "{}:{}/{}",
                dependency.package.namespace,
                dependency.package.name,
                name.interface_name()
            ),
            name: name.name.clone(),
        }),
        TypeExpr::List(element) => {
            TypeExpr::List(Box::new(qualify_type(Some(dependency), element)))
        }
        TypeExpr::FixedLengthList(element, len) => {
            TypeExpr::FixedLengthList(Box::new(qualify_type(Some(dependency), element)), *len)
        }
        TypeExpr::Map(key, value) => TypeExpr::Map(
            Box::new(qualify_type(Some(dependency), key)),
            Box::new(qualify_type(Some(dependency), value)),
        ),
        TypeExpr::Option(payload) => {
            TypeExpr::Option(Box::new(qualify_type(Some(dependency), payload)))
        }
        TypeExpr::Result(result) => TypeExpr::Result(ResultExpr {
            ok: result
                .ok
                .as_ref()
                .map(|ty| Box::new(qualify_type(Some(dependency), ty))),
            err: result
                .err
                .as_ref()
                .map(|ty| Box::new(qualify_type(Some(dependency), ty))),
        }),
        _ => ty.clone(),
    }
}

fn dependency_pkg_prefix(dependency: &Dependency) -> String {
    format!(
        "{}{}",
        ident::proto_pascal(&dependency.package.namespace),
        ident::proto_pascal(&dependency.package.name)
    )
}

fn dependency_shape_name(dependency: &Dependency, name: &QualifiedName) -> String {
    ident::proto_dependency_shape_name(
        &dependency.package.namespace,
        &dependency.package.name,
        name.interface_name(),
        &name.name,
    )
}

struct InterfaceGlueEmitter<'a> {
    ctx: &'a PackageEmitContext<'a>,
    interface: &'a Interface,
    local_stems: &'a BTreeMap<&'a str, &'a str>,
    imports: GlueImports,
}

#[allow(clippy::too_many_lines)]
fn emit_interface_glue(
    ctx: &PackageEmitContext<'_>,
    interface: &Interface,
    iface_stem: &str,
    local_stems: &BTreeMap<&str, &str>,
) -> Result<String> {
    let mut exported_names: BTreeMap<String, String> = BTreeMap::new();
    let scope = format!("interface `{}`", interface.name);
    for def in &interface.types {
        let export_ident = ts_value_ident(&def.name, "type glue")?;
        if export_ident == "functions" {
            contract_bail!(
                "type `{}/{}` maps to reserved TypeScript glue export `functions`",
                interface.name,
                def.name
            );
        }
        insert_name(
            &mut exported_names,
            &export_ident,
            &format!("type {}/{}", interface.name, def.name),
            &scope,
        )?;
    }

    let mut emitter = InterfaceGlueEmitter {
        ctx,
        interface,
        local_stems,
        imports: GlueImports::default(),
    };

    let mut body = String::new();
    let mut first = true;
    for def in &interface.types {
        if !first {
            writeln!(body)?;
        }
        first = false;
        emitter.emit_type(&mut body, def)?;
    }

    if !interface.functions.is_empty() {
        if !first {
            writeln!(body)?;
        }
        first = false;
        emitter.emit_functions(&mut body)?;
    }

    let mut out = String::new();
    writeln!(out, "{}", ctx.header)?;
    writeln!(
        out,
        "// source: {}:{}@{} (interface {})",
        ctx.model.package.namespace,
        ctx.model.package.name,
        ctx.model.package.version,
        interface.name
    )?;

    let root_prefix = "../".repeat(ctx.file_depth);
    let mut import_lines: Vec<String> = Vec::new();
    if emitter.imports.has("create") {
        import_lines.push("import { create as _wf_create } from \"@bufbuild/protobuf\";".into());
    }
    if emitter.imports.has("error") {
        import_lines.push(format!(
            "import {{ WitforgeGlueError as _wf_Error }} from \"{root_prefix}error.js\";"
        ));
    }
    if emitter.imports.has("helpers") {
        import_lines.push(format!(
            "import * as _wf_h from \"{root_prefix}helpers.js\";"
        ));
    }
    if !emitter.imports.plain_shared_types.is_empty() {
        let spec = resolve_import(ctx.plain_root, ctx.file_depth, "witforge_types.js");
        let items: Vec<String> = emitter
            .imports
            .plain_shared_types
            .iter()
            .map(|name| format!("{name} as _wf_{name}"))
            .collect();
        import_lines.push(format!(
            "import type {{ {} }} from \"{spec}\";",
            items.join(", ")
        ));
    }
    if !emitter.imports.plain_shared_values.is_empty() {
        let spec = resolve_import(ctx.plain_root, ctx.file_depth, "witforge_types.js");
        let items: Vec<String> = emitter
            .imports
            .plain_shared_values
            .iter()
            .map(|name| format!("{name} as _wf_{name}"))
            .collect();
        import_lines.push(format!(
            "import {{ {} }} from \"{spec}\";",
            items.join(", ")
        ));
    }
    if emitter.imports.has("local_plain") {
        let spec = resolve_import(
            ctx.plain_root,
            ctx.file_depth,
            &format!("{}/{iface_stem}.js", ctx.plain_pkg_rel),
        );
        import_lines.push(format!("import type * as _wf_plain from \"{spec}\";"));
    }
    for (spec, alias) in &emitter.imports.plain_type_imports {
        import_lines.push(format!("import type * as {alias} from \"{spec}\";"));
    }
    if emitter.imports.has("local_proto_value") {
        let spec = resolve_import(
            ctx.proto_root,
            ctx.file_depth,
            &format!("{}_pb.js", ctx.proto_file_stem),
        );
        import_lines.push(format!("import * as _wf_proto from \"{spec}\";"));
    } else if emitter.imports.has("local_proto_type") {
        let spec = resolve_import(
            ctx.proto_root,
            ctx.file_depth,
            &format!("{}_pb.js", ctx.proto_file_stem),
        );
        import_lines.push(format!("import type * as _wf_proto from \"{spec}\";"));
    }
    for (spec, alias) in &emitter.imports.proto_type_imports {
        import_lines.push(format!("import type * as {alias} from \"{spec}\";"));
    }
    for (spec, alias) in &emitter.imports.glue_value_imports {
        import_lines.push(format!("import * as {alias} from \"{spec}\";"));
    }

    if !import_lines.is_empty() {
        writeln!(out)?;
        for line in import_lines {
            writeln!(out, "{line}")?;
        }
    }

    writeln!(out)?;
    if first {
        writeln!(out, "export {{}};")?;
    } else {
        out.push_str(&body);
    }
    Ok(out)
}

impl<'a> InterfaceGlueEmitter<'a> {
    fn named(&self, name: &QualifiedName) -> Result<&'a TypeDef> {
        self.ctx.model.type_def(name).with_context(|| {
            format!(
                "named type `{}/{}` is not in the model",
                name.interface, name.name
            )
        })
    }

    fn foreign_type_def(
        &self,
        context: Option<&'a Dependency>,
        name: &QualifiedName,
    ) -> Result<Option<(&'a Dependency, &'a TypeDef)>> {
        if let Some((namespace, package)) = name.package() {
            let dependency = self
                .ctx
                .model
                .dependency_package(namespace, package)
                .with_context(|| {
                    format!("dependency `{namespace}:{package}` is not in the model")
                })?;
            let def = dependency
                .interfaces
                .iter()
                .find(|iface| iface.name == name.interface_name())
                .and_then(|iface| iface.types.iter().find(|def| def.name == name.name))
                .with_context(|| format!("named type `{name}` is not in the dependency model"))?;
            return Ok(Some((dependency, def)));
        }
        let Some(dependency) = context else {
            return Ok(None);
        };
        let def = dependency
            .interfaces
            .iter()
            .find(|iface| iface.name == name.interface_name())
            .and_then(|iface| iface.types.iter().find(|def| def.name == name.name))
            .with_context(|| format!("named type `{name}` is not in the dependency model"))?;
        Ok(Some((dependency, def)))
    }

    fn resolve_type_def(
        &self,
        context: Option<&'a Dependency>,
        name: &QualifiedName,
    ) -> Result<(Option<&'a Dependency>, &'a TypeDef)> {
        if let Some((dep, def)) = self.foreign_type_def(context, name)? {
            return Ok((Some(dep), def));
        }
        Ok((None, self.named(name)?))
    }

    fn is_same_package(&self, a: Option<&Dependency>, b: Option<&Dependency>) -> bool {
        let pkg_a = a.map_or(&self.ctx.model.package, |dep| &dep.package);
        let pkg_b = b.map_or(&self.ctx.model.package, |dep| &dep.package);
        pkg_a.namespace == pkg_b.namespace && pkg_a.name == pkg_b.name
    }

    fn resolve_foreign_named(
        &self,
        ty: &TypeExpr,
    ) -> Result<Option<(Dependency, QualifiedName, TypeDefKind)>> {
        match ty {
            TypeExpr::Named(name) => {
                if name.is_foreign() {
                    let (dep, def) = self
                        .foreign_type_def(None, name)?
                        .context("foreign type needs a dependency package")?;
                    match &def.kind {
                        TypeDefKind::Alias(target) => {
                            let qualified = qualify_type(Some(dep), target);
                            self.resolve_foreign_named(&qualified)
                        }
                        other => Ok(Some((dep.clone(), name.clone(), other.clone()))),
                    }
                } else {
                    match &self.named(name)?.kind {
                        TypeDefKind::Alias(target) => self.resolve_foreign_named(target),
                        _ => Ok(None),
                    }
                }
            }
            _ => Ok(None),
        }
    }

    fn form(&self, ty: &TypeExpr) -> Result<Form> {
        match ty {
            TypeExpr::Bool
            | TypeExpr::U8
            | TypeExpr::U16
            | TypeExpr::U32
            | TypeExpr::U64
            | TypeExpr::S8
            | TypeExpr::S16
            | TypeExpr::S32
            | TypeExpr::S64
            | TypeExpr::F32
            | TypeExpr::F64
            | TypeExpr::Char
            | TypeExpr::String => Ok(Form::Scalar),
            TypeExpr::List(element) | TypeExpr::FixedLengthList(element, _)
                if self.ctx.model.resolves_to_u8(element) =>
            {
                Ok(Form::Bytes)
            }
            TypeExpr::List(_) | TypeExpr::FixedLengthList(_, _) => Ok(Form::List),
            TypeExpr::Map(_, _) => Ok(Form::Map),
            TypeExpr::Option(_) => Ok(Form::Option),
            TypeExpr::Result(_) => Ok(Form::Message),
            TypeExpr::Named(name) => {
                if name.is_foreign() {
                    return self.foreign_form(name);
                }
                let def = self.named(name)?;
                match &def.kind {
                    TypeDefKind::Alias(target) => self.form(target),
                    TypeDefKind::Enum(_) => Ok(Form::Enum),
                    TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _)
                        if self.ctx.model.resolves_to_u8(element) =>
                    {
                        Ok(Form::Bytes)
                    }
                    TypeDefKind::List(_) | TypeDefKind::FixedLengthList(_, _) => Ok(Form::List),
                    TypeDefKind::Map(_, _) => Ok(Form::Map),
                    TypeDefKind::Option(_) => Ok(Form::Option),
                    TypeDefKind::Record(_)
                    | TypeDefKind::Variant(_)
                    | TypeDefKind::Flags(_)
                    | TypeDefKind::Result(_) => Ok(Form::Message),
                }
            }
        }
    }

    fn foreign_form(&self, name: &QualifiedName) -> Result<Form> {
        let (dep, def) = self
            .foreign_type_def(None, name)?
            .context("foreign type needs a dependency package")?;
        self.foreign_form_kind(Some(dep), &def.kind)
    }

    fn foreign_form_kind(&self, context: Option<&Dependency>, kind: &TypeDefKind) -> Result<Form> {
        match kind {
            TypeDefKind::Alias(target) => self.foreign_form_expr(context, target),
            TypeDefKind::Enum(_) => Ok(Form::Enum),
            TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _)
                if self.ctx.model.resolves_to_u8_in(context, element) =>
            {
                Ok(Form::Bytes)
            }
            TypeDefKind::List(_) | TypeDefKind::FixedLengthList(_, _) => Ok(Form::List),
            TypeDefKind::Map(_, _) => Ok(Form::Map),
            TypeDefKind::Option(_) => Ok(Form::Option),
            TypeDefKind::Record(_)
            | TypeDefKind::Variant(_)
            | TypeDefKind::Flags(_)
            | TypeDefKind::Result(_) => Ok(Form::Message),
        }
    }

    fn foreign_form_expr(&self, context: Option<&Dependency>, ty: &TypeExpr) -> Result<Form> {
        match ty {
            TypeExpr::Named(name) => {
                if name.package().is_some() {
                    self.foreign_form(name)
                } else {
                    let (dep, def) = self
                        .foreign_type_def(context, name)?
                        .context("foreign alias target has no dependency context")?;
                    self.foreign_form_kind(Some(dep), &def.kind)
                }
            }
            TypeExpr::List(element) | TypeExpr::FixedLengthList(element, _)
                if self.ctx.model.resolves_to_u8_in(context, element) =>
            {
                Ok(Form::Bytes)
            }
            TypeExpr::List(_) | TypeExpr::FixedLengthList(_, _) => Ok(Form::List),
            TypeExpr::Map(_, _) => Ok(Form::Map),
            TypeExpr::Option(_) => Ok(Form::Option),
            TypeExpr::Result(_) => Ok(Form::Message),
            _ => Ok(Form::Scalar),
        }
    }

    fn number(&self, interface: &str, ty: &str, member: &str) -> Result<u32> {
        let key = format!(
            "{}:{}/{interface}/{ty}.{member}",
            self.ctx.model.package.namespace, self.ctx.model.package.name
        );
        self.ctx
            .lock
            .get(&key)
            .map(|entry| entry.number)
            .with_context(|| format!("lockfile has no number for `{key}`"))
    }

    // --- Shape & wrapper name calculation (matches `proto.rs` & `glue.rs` verbatim) ---

    fn shape_name(&self, ty: &TypeExpr) -> Result<String> {
        match ty {
            TypeExpr::Bool => Ok("Bool".to_string()),
            TypeExpr::U8 => Ok("U8".to_string()),
            TypeExpr::U16 => Ok("U16".to_string()),
            TypeExpr::U32 => Ok("U32".to_string()),
            TypeExpr::U64 => Ok("U64".to_string()),
            TypeExpr::S8 => Ok("S8".to_string()),
            TypeExpr::S16 => Ok("S16".to_string()),
            TypeExpr::S32 => Ok("S32".to_string()),
            TypeExpr::S64 => Ok("S64".to_string()),
            TypeExpr::F32 => Ok("F32".to_string()),
            TypeExpr::F64 => Ok("F64".to_string()),
            TypeExpr::Char => Ok("Char".to_string()),
            TypeExpr::String => Ok("String".to_string()),
            TypeExpr::List(element) | TypeExpr::FixedLengthList(element, _) => {
                Ok(format!("ListOf{}", self.shape_name(element)?))
            }
            TypeExpr::Map(key, value) => Ok(format!(
                "MapOf{}And{}",
                self.shape_name(key)?,
                self.shape_name(value)?
            )),
            TypeExpr::Option(payload) => Ok(format!("OptionOf{}", self.shape_name(payload)?)),
            TypeExpr::Result(result) => Ok(format!(
                "ResultOf{}And{}",
                self.shape_slot(result.ok.as_deref())?,
                self.shape_slot(result.err.as_deref())?
            )),
            TypeExpr::Named(name) => {
                if name.is_foreign() {
                    return self.foreign_shape_name(name);
                }
                let def = self.named(name)?;
                match &def.kind {
                    TypeDefKind::Alias(target) => self.shape_name(target),
                    TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _) => {
                        Ok(format!("ListOf{}", self.shape_name(element)?))
                    }
                    TypeDefKind::Map(key, value) => Ok(format!(
                        "MapOf{}And{}",
                        self.shape_name(key)?,
                        self.shape_name(value)?
                    )),
                    TypeDefKind::Option(payload) => {
                        Ok(format!("OptionOf{}", self.shape_name(payload)?))
                    }
                    TypeDefKind::Result(result) => Ok(format!(
                        "ResultOf{}And{}",
                        self.shape_slot(result.ok.as_deref())?,
                        self.shape_slot(result.err.as_deref())?
                    )),
                    TypeDefKind::Record(_)
                    | TypeDefKind::Variant(_)
                    | TypeDefKind::Enum(_)
                    | TypeDefKind::Flags(_) => {
                        Ok(ident::proto_type_name(&name.interface, &name.name))
                    }
                }
            }
        }
    }

    fn shape_slot(&self, slot: Option<&TypeExpr>) -> Result<String> {
        slot.map_or_else(|| Ok("Empty".to_string()), |ty| self.shape_name(ty))
    }

    fn foreign_shape_name(&self, name: &QualifiedName) -> Result<String> {
        let (dep, def) = self
            .foreign_type_def(None, name)?
            .context("foreign type needs a dependency package")?;
        self.foreign_shape_name_for_caller(None, dep, name, &def.kind)
    }

    fn owner_shape_name_ty(&self, owner: Option<&Dependency>, ty: &TypeExpr) -> Result<String> {
        match ty {
            TypeExpr::Bool => Ok("Bool".to_string()),
            TypeExpr::U8 => Ok("U8".to_string()),
            TypeExpr::U16 => Ok("U16".to_string()),
            TypeExpr::U32 => Ok("U32".to_string()),
            TypeExpr::U64 => Ok("U64".to_string()),
            TypeExpr::S8 => Ok("S8".to_string()),
            TypeExpr::S16 => Ok("S16".to_string()),
            TypeExpr::S32 => Ok("S32".to_string()),
            TypeExpr::S64 => Ok("S64".to_string()),
            TypeExpr::F32 => Ok("F32".to_string()),
            TypeExpr::F64 => Ok("F64".to_string()),
            TypeExpr::Char => Ok("Char".to_string()),
            TypeExpr::String => Ok("String".to_string()),
            TypeExpr::List(element) | TypeExpr::FixedLengthList(element, _) => Ok(format!(
                "ListOf{}",
                self.owner_shape_name_ty(owner, element)?
            )),
            TypeExpr::Map(key, value) => Ok(format!(
                "MapOf{}And{}",
                self.owner_shape_name_ty(owner, key)?,
                self.owner_shape_name_ty(owner, value)?
            )),
            TypeExpr::Option(payload) => Ok(format!(
                "OptionOf{}",
                self.owner_shape_name_ty(owner, payload)?
            )),
            TypeExpr::Result(result) => self.owner_result_shape_name(owner, result),
            TypeExpr::Named(name) => {
                let (target_dep, def) = self.resolve_type_def(owner, name)?;
                if self.is_same_package(owner, target_dep) {
                    match &def.kind {
                        TypeDefKind::Alias(target) => self.owner_shape_name_ty(owner, target),
                        TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _) => {
                            Ok(format!(
                                "ListOf{}",
                                self.owner_shape_name_ty(owner, element)?
                            ))
                        }
                        TypeDefKind::Map(key, value) => Ok(format!(
                            "MapOf{}And{}",
                            self.owner_shape_name_ty(owner, key)?,
                            self.owner_shape_name_ty(owner, value)?
                        )),
                        TypeDefKind::Option(payload) => {
                            if matches!(
                                self.foreign_form_expr(owner, payload)?,
                                Form::List | Form::Map | Form::Option
                            ) {
                                Ok(format!(
                                    "OptionOf{}",
                                    ident::proto_type_name(name.interface_name(), &name.name)
                                ))
                            } else {
                                Ok(format!(
                                    "OptionOf{}",
                                    self.owner_shape_name_ty(owner, payload)?
                                ))
                            }
                        }
                        TypeDefKind::Result(result) => self.owner_result_shape_name(owner, result),
                        TypeDefKind::Record(_)
                        | TypeDefKind::Variant(_)
                        | TypeDefKind::Enum(_)
                        | TypeDefKind::Flags(_) => {
                            Ok(ident::proto_type_name(name.interface_name(), &name.name))
                        }
                    }
                } else {
                    let dep = target_dep.context("foreign type has no dependency context")?;
                    self.foreign_shape_name_for_caller(owner, dep, name, &def.kind)
                }
            }
        }
    }

    fn owner_result_shape_name(
        &self,
        owner: Option<&Dependency>,
        result: &ResultExpr,
    ) -> Result<String> {
        let ok = match &result.ok {
            Some(ty) => self.owner_shape_name_ty(owner, ty)?,
            None => "Empty".to_string(),
        };
        let err = match &result.err {
            Some(ty) => self.owner_shape_name_ty(owner, ty)?,
            None => "Empty".to_string(),
        };
        Ok(format!("ResultOf{ok}And{err}"))
    }

    fn element_uses_dependency_wrapper(&self, owner: &Dependency, ty: &TypeExpr) -> Result<bool> {
        match ty {
            TypeExpr::Bool
            | TypeExpr::U8
            | TypeExpr::U16
            | TypeExpr::U32
            | TypeExpr::U64
            | TypeExpr::S8
            | TypeExpr::S16
            | TypeExpr::S32
            | TypeExpr::S64
            | TypeExpr::F32
            | TypeExpr::F64
            | TypeExpr::Char
            | TypeExpr::String => Ok(false),
            TypeExpr::List(element) | TypeExpr::FixedLengthList(element, _) => {
                Ok(!self.ctx.model.resolves_to_u8_in(Some(owner), element))
            }
            TypeExpr::Map(_, _) | TypeExpr::Option(_) | TypeExpr::Result(_) => Ok(true),
            TypeExpr::Named(name) => {
                let (resolved_dep, def) = self.resolve_type_def(Some(owner), name)?;
                match &def.kind {
                    TypeDefKind::Alias(target) => {
                        let next_owner = resolved_dep.unwrap_or(owner);
                        self.element_uses_dependency_wrapper(next_owner, target)
                    }
                    TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _) => {
                        Ok(!self.ctx.model.resolves_to_u8_in(resolved_dep, element))
                    }
                    TypeDefKind::Map(_, _) | TypeDefKind::Option(_) => Ok(true),
                    TypeDefKind::Record(_)
                    | TypeDefKind::Variant(_)
                    | TypeDefKind::Enum(_)
                    | TypeDefKind::Flags(_)
                    | TypeDefKind::Result(_) => Ok(false),
                }
            }
        }
    }

    fn foreign_shape_name_for_caller(
        &self,
        caller: Option<&Dependency>,
        owner: &Dependency,
        name: &QualifiedName,
        kind: &TypeDefKind,
    ) -> Result<String> {
        match kind {
            TypeDefKind::Alias(target) => self.foreign_shape_name_expr(caller, owner, target),
            TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _) => {
                if self.element_uses_dependency_wrapper(owner, element)? {
                    Ok(format!(
                        "ListOf{}{}",
                        dependency_pkg_prefix(owner),
                        self.owner_shape_name_ty(Some(owner), element)?
                    ))
                } else {
                    Ok(format!(
                        "ListOf{}",
                        self.foreign_shape_name_expr(caller, owner, element)?
                    ))
                }
            }
            TypeDefKind::Map(key, value) => {
                let k = self.foreign_shape_name_expr(caller, owner, key)?;
                let v = if self.element_uses_dependency_wrapper(owner, value)? {
                    format!(
                        "{}{}",
                        dependency_pkg_prefix(owner),
                        self.owner_shape_name_ty(Some(owner), value)?
                    )
                } else {
                    self.foreign_shape_name_expr(caller, owner, value)?
                };
                Ok(format!("MapOf{k}And{v}"))
            }
            TypeDefKind::Option(payload) => {
                if matches!(
                    self.foreign_form_expr(Some(owner), payload)?,
                    Form::List | Form::Map | Form::Option
                ) {
                    Ok(format!("OptionOf{}", dependency_shape_name(owner, name)))
                } else {
                    Ok(format!(
                        "OptionOf{}",
                        self.foreign_shape_name_expr(caller, owner, payload)?
                    ))
                }
            }
            TypeDefKind::Result(result) => self.foreign_result_shape_name(caller, owner, result),
            TypeDefKind::Record(_)
            | TypeDefKind::Variant(_)
            | TypeDefKind::Enum(_)
            | TypeDefKind::Flags(_) => Ok(dependency_shape_name(owner, name)),
        }
    }

    fn foreign_shape_name_expr(
        &self,
        caller: Option<&Dependency>,
        owner: &Dependency,
        ty: &TypeExpr,
    ) -> Result<String> {
        match ty {
            TypeExpr::Bool => Ok("Bool".to_string()),
            TypeExpr::U8 => Ok("U8".to_string()),
            TypeExpr::U16 => Ok("U16".to_string()),
            TypeExpr::U32 => Ok("U32".to_string()),
            TypeExpr::U64 => Ok("U64".to_string()),
            TypeExpr::S8 => Ok("S8".to_string()),
            TypeExpr::S16 => Ok("S16".to_string()),
            TypeExpr::S32 => Ok("S32".to_string()),
            TypeExpr::S64 => Ok("S64".to_string()),
            TypeExpr::F32 => Ok("F32".to_string()),
            TypeExpr::F64 => Ok("F64".to_string()),
            TypeExpr::Char => Ok("Char".to_string()),
            TypeExpr::String => Ok("String".to_string()),
            TypeExpr::List(element) | TypeExpr::FixedLengthList(element, _) => Ok(format!(
                "ListOf{}",
                self.foreign_shape_name_expr(caller, owner, element)?
            )),
            TypeExpr::Map(key, value) => Ok(format!(
                "MapOf{}And{}",
                self.foreign_shape_name_expr(caller, owner, key)?,
                self.foreign_shape_name_expr(caller, owner, value)?
            )),
            TypeExpr::Option(payload) => Ok(format!(
                "OptionOf{}",
                self.foreign_shape_name_expr(caller, owner, payload)?
            )),
            TypeExpr::Result(result) => self.foreign_result_shape_name(caller, owner, result),
            TypeExpr::Named(name) => {
                let (target_dep, def) = self.resolve_type_def(Some(owner), name)?;
                let dep = target_dep.context("foreign type has no dependency context")?;
                self.foreign_shape_name_for_caller(caller, dep, name, &def.kind)
            }
        }
    }

    fn foreign_result_shape_name(
        &self,
        caller: Option<&Dependency>,
        owner: &Dependency,
        result: &ResultExpr,
    ) -> Result<String> {
        let ok = match &result.ok {
            Some(ty) => self.foreign_shape_name_expr(caller, owner, ty)?,
            None => "Empty".to_string(),
        };
        let err = match &result.err {
            Some(ty) => self.foreign_shape_name_expr(caller, owner, ty)?,
            None => "Empty".to_string(),
        };
        Ok(format!("ResultOf{ok}And{err}"))
    }

    // --- Plain & Proto TypeScript type spellings ---

    fn local_proto_type_ref(&mut self, proto_name: &str) -> String {
        self.imports.use_local_proto_type();
        format!("_wf_proto.{}", self.ctx.es_names.shape(proto_name))
    }

    fn local_proto_schema_ref(&mut self, proto_name: &str) -> String {
        self.imports.use_local_proto_value();
        format!("_wf_proto.{}", self.ctx.es_names.desc(proto_name))
    }

    fn local_proto_enum_value_ref(&mut self, proto_enum: &str, proto_value: &str) -> String {
        self.imports.use_local_proto_value();
        let shape = self.ctx.es_names.shape(proto_enum);
        let member = self.ctx.es_names.enum_member(proto_enum, proto_value);
        format!("_wf_proto.{shape}.{member}")
    }

    fn dep_proto_type_ref(&mut self, dependency: &Dependency, proto_name: &str) -> Result<String> {
        let proto_file = self
            .ctx
            .dep_layout
            .proto_file_name(self.ctx.root_major, dependency);
        let stem = proto_file
            .strip_suffix(".proto")
            .unwrap_or(&proto_file)
            .to_string();
        let es_names = self
            .ctx
            .es_files
            .get(&proto_file)
            .with_context(|| format!("missing planned dependency proto file `{proto_file}`"))?;
        let spec = resolve_import(
            self.ctx.proto_root,
            self.ctx.file_depth,
            &format!("{stem}_pb.js"),
        );
        let seg = dep_package_segment(&dependency.package.namespace, &dependency.package.name);
        let alias = self.imports.proto_type_alias(spec, &format!("_wf_p_{seg}"));
        Ok(format!("{alias}.{}", es_names.shape(proto_name)))
    }

    fn plain_named_type(&mut self, name: &QualifiedName) -> Result<String> {
        self.ctx.model.type_def(name).with_context(|| {
            format!(
                "named type `{}/{}` is not in the model",
                name.interface, name.name
            )
        })?;
        let ts_ty = ts_type_ident(&name.name, "type")?;
        if let Some((ns, pkg)) = name.package() {
            let seg = safe_pkg_segment(ns, pkg)?;
            let iface_stem = safe_interface_file_stem(name.interface_name())?;
            let rel = if self.ctx.dep_layout.is_scoped(ns, pkg) {
                format!(
                    "witforge_deps/{}/{seg}/{iface_stem}.js",
                    polyglot::major_dir_name(self.ctx.root_major)
                )
            } else {
                format!("witforge_deps/{seg}/{iface_stem}.js")
            };
            let spec = resolve_import(self.ctx.plain_root, self.ctx.file_depth, &rel);
            let alias = self
                .imports
                .plain_type_alias(spec, &format!("_wf_dp_{seg}_{iface_stem}"));
            return Ok(format!("{alias}.{ts_ty}"));
        }
        if name.interface == self.interface.name {
            self.imports.use_local_plain();
            return Ok(format!("_wf_plain.{ts_ty}"));
        }
        let stem = self
            .local_stems
            .get(name.interface.as_str())
            .copied()
            .map(str::to_string)
            .map_or_else(|| safe_interface_file_stem(&name.interface), Ok)?;
        let spec = resolve_import(
            self.ctx.plain_root,
            self.ctx.file_depth,
            &format!("{}/{stem}.js", self.ctx.plain_pkg_rel),
        );
        let alias = self
            .imports
            .plain_type_alias(spec, &format!("_wf_ip_{stem}"));
        Ok(format!("{alias}.{ts_ty}"))
    }

    fn plain_type(&mut self, ty: &TypeExpr) -> Result<String> {
        match ty {
            TypeExpr::Bool => Ok("boolean".to_string()),
            TypeExpr::U8
            | TypeExpr::U16
            | TypeExpr::U32
            | TypeExpr::S8
            | TypeExpr::S16
            | TypeExpr::S32
            | TypeExpr::F32
            | TypeExpr::F64 => Ok("number".to_string()),
            TypeExpr::U64 | TypeExpr::S64 => Ok("bigint".to_string()),
            TypeExpr::Char | TypeExpr::String => Ok("string".to_string()),
            TypeExpr::Named(name) => self.plain_named_type(name),
            TypeExpr::List(elem) | TypeExpr::FixedLengthList(elem, _) => {
                if self.ctx.model.resolves_to_u8(elem) {
                    return Ok("Uint8Array".to_string());
                }
                let inner = self.plain_type(elem)?;
                let needs_parens = matches!(
                    elem.as_ref(),
                    TypeExpr::Result(_) | TypeExpr::List(_) | TypeExpr::FixedLengthList(_, _)
                ) && inner != "Uint8Array";
                if needs_parens {
                    Ok(format!("readonly ({inner})[]"))
                } else {
                    Ok(format!("readonly {inner}[]"))
                }
            }
            TypeExpr::Map(key, value) => {
                let k = self.plain_type(key)?;
                let v = self.plain_type(value)?;
                Ok(format!("ReadonlyMap<{k}, {v}>"))
            }
            TypeExpr::Option(payload) => {
                self.imports.use_option_type();
                let inner = self.plain_type(payload)?;
                Ok(format!("_wf_Option<{inner}>"))
            }
            TypeExpr::Result(result) => {
                let ok = match &result.ok {
                    Some(ty) => format!(
                        "{{ readonly tag: \"ok\"; readonly value: {} }}",
                        self.plain_type(ty)?
                    ),
                    None => "{ readonly tag: \"ok\" }".to_string(),
                };
                let err = match &result.err {
                    Some(ty) => format!(
                        "{{ readonly tag: \"err\"; readonly error: {} }}",
                        self.plain_type(ty)?
                    ),
                    None => "{ readonly tag: \"err\" }".to_string(),
                };
                Ok(format!("{ok} | {err}"))
            }
        }
    }

    fn proto_map_key_ts_type(key: &TypeExpr) -> Result<&'static str> {
        match key {
            TypeExpr::String | TypeExpr::Bool | TypeExpr::U64 | TypeExpr::S64 => Ok("string"),
            TypeExpr::U8
            | TypeExpr::U16
            | TypeExpr::U32
            | TypeExpr::S8
            | TypeExpr::S16
            | TypeExpr::S32
            | TypeExpr::Char => Ok("number"),
            _ => bail!("map key `{key:?}` is not a valid primitive map key"),
        }
    }

    fn proto_direct_type(&mut self, ty: &TypeExpr) -> Result<String> {
        match ty {
            TypeExpr::Bool => Ok("boolean".to_string()),
            TypeExpr::U8
            | TypeExpr::U16
            | TypeExpr::U32
            | TypeExpr::S8
            | TypeExpr::S16
            | TypeExpr::S32
            | TypeExpr::F32
            | TypeExpr::F64
            | TypeExpr::Char => Ok("number".to_string()),
            TypeExpr::U64 | TypeExpr::S64 => Ok("bigint".to_string()),
            TypeExpr::String => Ok("string".to_string()),
            TypeExpr::List(element) | TypeExpr::FixedLengthList(element, _)
                if self.ctx.model.resolves_to_u8(element) =>
            {
                Ok("Uint8Array".to_string())
            }
            TypeExpr::List(element) | TypeExpr::FixedLengthList(element, _) => {
                Ok(format!("{}[]", self.proto_singular_type(element)?))
            }
            TypeExpr::Map(key, value) => Ok(format!(
                "{{ [key: {}]: {} }}",
                Self::proto_map_key_ts_type(key)?,
                self.proto_singular_type(value)?
            )),
            TypeExpr::Option(payload) => Ok(format!(
                "{} | undefined",
                self.proto_singular_type(payload)?
            )),
            TypeExpr::Result(_) => {
                let shape = self.shape_name(ty)?;
                Ok(self.local_proto_type_ref(&format!("Witforge{shape}")))
            }
            TypeExpr::Named(name) => {
                if name.is_foreign() {
                    return self.foreign_proto_direct_type(name);
                }
                let def = self.named(name)?;
                match &def.kind {
                    TypeDefKind::Alias(target) => self.proto_direct_type(target),
                    TypeDefKind::Record(_)
                    | TypeDefKind::Variant(_)
                    | TypeDefKind::Flags(_)
                    | TypeDefKind::Result(_)
                    | TypeDefKind::Enum(_) => {
                        let proto_name = ident::proto_type_name(&name.interface, &name.name);
                        Ok(self.local_proto_type_ref(&proto_name))
                    }
                    TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _)
                        if self.ctx.model.resolves_to_u8(element) =>
                    {
                        Ok("Uint8Array".to_string())
                    }
                    TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _) => {
                        Ok(format!("{}[]", self.proto_singular_type(element)?))
                    }
                    TypeDefKind::Map(key, value) => Ok(format!(
                        "{{ [key: {}]: {} }}",
                        Self::proto_map_key_ts_type(key)?,
                        self.proto_singular_type(value)?
                    )),
                    TypeDefKind::Option(payload) => {
                        let inner =
                            if matches!(self.form(payload)?, Form::List | Form::Map | Form::Option)
                            {
                                let proto_name =
                                    ident::proto_type_name(&name.interface, &name.name);
                                self.local_proto_type_ref(&proto_name)
                            } else {
                                self.proto_singular_type(payload)?
                            };
                        Ok(format!("{inner} | undefined"))
                    }
                }
            }
        }
    }

    fn proto_singular_type(&mut self, ty: &TypeExpr) -> Result<String> {
        match ty {
            TypeExpr::Bool => Ok("boolean".to_string()),
            TypeExpr::U8
            | TypeExpr::U16
            | TypeExpr::U32
            | TypeExpr::S8
            | TypeExpr::S16
            | TypeExpr::S32
            | TypeExpr::F32
            | TypeExpr::F64
            | TypeExpr::Char => Ok("number".to_string()),
            TypeExpr::U64 | TypeExpr::S64 => Ok("bigint".to_string()),
            TypeExpr::String => Ok("string".to_string()),
            TypeExpr::List(element) | TypeExpr::FixedLengthList(element, _)
                if self.ctx.model.resolves_to_u8(element) =>
            {
                Ok("Uint8Array".to_string())
            }
            TypeExpr::List(element) | TypeExpr::FixedLengthList(element, _) => {
                let name = format!("WitforgeListOf{}", self.shape_name(element)?);
                Ok(self.local_proto_type_ref(&name))
            }
            TypeExpr::Map(key, value) => {
                let name = format!(
                    "WitforgeMapOf{}And{}",
                    self.shape_name(key)?,
                    self.shape_name(value)?
                );
                Ok(self.local_proto_type_ref(&name))
            }
            TypeExpr::Option(payload) => {
                let name = format!("WitforgeOptionOf{}", self.shape_name(payload)?);
                Ok(self.local_proto_type_ref(&name))
            }
            TypeExpr::Result(_) => {
                let shape = self.shape_name(ty)?;
                Ok(self.local_proto_type_ref(&format!("Witforge{shape}")))
            }
            TypeExpr::Named(name) => {
                if name.is_foreign() {
                    return self.foreign_proto_singular_type(name);
                }
                let def = self.named(name)?;
                match &def.kind {
                    TypeDefKind::Alias(target) => self.proto_singular_type(target),
                    TypeDefKind::Record(_)
                    | TypeDefKind::Variant(_)
                    | TypeDefKind::Flags(_)
                    | TypeDefKind::Result(_)
                    | TypeDefKind::Enum(_) => {
                        let proto_name = ident::proto_type_name(&name.interface, &name.name);
                        Ok(self.local_proto_type_ref(&proto_name))
                    }
                    TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _)
                        if self.ctx.model.resolves_to_u8(element) =>
                    {
                        Ok("Uint8Array".to_string())
                    }
                    TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _) => {
                        let name = format!("WitforgeListOf{}", self.shape_name(element)?);
                        Ok(self.local_proto_type_ref(&name))
                    }
                    TypeDefKind::Map(key, value) => {
                        let name = format!(
                            "WitforgeMapOf{}And{}",
                            self.shape_name(key)?,
                            self.shape_name(value)?
                        );
                        Ok(self.local_proto_type_ref(&name))
                    }
                    TypeDefKind::Option(payload) => {
                        let name =
                            if matches!(self.form(payload)?, Form::List | Form::Map | Form::Option)
                            {
                                format!(
                                    "WitforgeOptionOf{}",
                                    ident::proto_type_name(&name.interface, &name.name)
                                )
                            } else {
                                format!("WitforgeOptionOf{}", self.shape_name(payload)?)
                            };
                        Ok(self.local_proto_type_ref(&name))
                    }
                }
            }
        }
    }

    fn foreign_proto_direct_type(&mut self, name: &QualifiedName) -> Result<String> {
        let (dep, def) = self
            .foreign_type_def(None, name)?
            .context("foreign type needs a dependency package")?;
        self.foreign_proto_direct_in(dep, name, &def.kind)
    }

    fn foreign_proto_direct_in(
        &mut self,
        owner: &'a Dependency,
        name: &QualifiedName,
        kind: &TypeDefKind,
    ) -> Result<String> {
        match kind {
            TypeDefKind::Alias(target) => self.foreign_proto_direct_expr(owner, target),
            TypeDefKind::Record(_)
            | TypeDefKind::Variant(_)
            | TypeDefKind::Flags(_)
            | TypeDefKind::Result(_)
            | TypeDefKind::Enum(_) => {
                let proto_name = ident::proto_type_name(name.interface_name(), &name.name);
                self.dep_proto_type_ref(owner, &proto_name)
            }
            TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _)
                if self.ctx.model.resolves_to_u8_in(Some(owner), element) =>
            {
                Ok("Uint8Array".to_string())
            }
            TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _) => Ok(format!(
                "{}[]",
                self.dependency_defined_proto_singular(owner, element)?
            )),
            TypeDefKind::Map(key, value) => Ok(format!(
                "{{ [key: {}]: {} }}",
                Self::proto_map_key_ts_type(key)?,
                self.dependency_defined_proto_singular(owner, value)?
            )),
            TypeDefKind::Option(payload) => {
                let inner = match self.foreign_form_expr(Some(owner), payload)? {
                    Form::List | Form::Map | Form::Option => {
                        let proto_name = ident::proto_type_name(name.interface_name(), &name.name);
                        self.dep_proto_type_ref(owner, &proto_name)?
                    }
                    Form::Scalar | Form::Bytes | Form::Enum | Form::Message => {
                        self.dependency_defined_proto_singular(owner, payload)?
                    }
                };
                Ok(format!("{inner} | undefined"))
            }
        }
    }

    fn foreign_proto_direct_expr(
        &mut self,
        owner: &'a Dependency,
        ty: &TypeExpr,
    ) -> Result<String> {
        match ty {
            TypeExpr::Named(name) => {
                if name.package().is_some() {
                    self.foreign_proto_direct_type(name)
                } else {
                    let (dep, def) = self
                        .foreign_type_def(Some(owner), name)?
                        .context("foreign alias target has no dependency context")?;
                    self.foreign_proto_direct_in(dep, name, &def.kind)
                }
            }
            TypeExpr::List(element) | TypeExpr::FixedLengthList(element, _)
                if self.ctx.model.resolves_to_u8_in(Some(owner), element) =>
            {
                Ok("Uint8Array".to_string())
            }
            TypeExpr::List(element) | TypeExpr::FixedLengthList(element, _) => Ok(format!(
                "{}[]",
                self.dependency_defined_proto_singular(owner, element)?
            )),
            TypeExpr::Map(key, value) => Ok(format!(
                "{{ [key: {}]: {} }}",
                Self::proto_map_key_ts_type(key)?,
                self.dependency_defined_proto_singular(owner, value)?
            )),
            TypeExpr::Option(payload) => Ok(format!(
                "{} | undefined",
                self.dependency_defined_proto_singular(owner, payload)?
            )),
            TypeExpr::Result(result) => {
                let name = format!(
                    "Witforge{}",
                    self.owner_result_shape_name(Some(owner), result)?
                );
                self.dep_proto_type_ref(owner, &name)
            }
            TypeExpr::Bool => Ok("boolean".to_string()),
            TypeExpr::U64 | TypeExpr::S64 => Ok("bigint".to_string()),
            TypeExpr::String => Ok("string".to_string()),
            _ => Ok("number".to_string()),
        }
    }

    #[allow(clippy::too_many_lines)]
    fn dependency_defined_proto_singular(
        &mut self,
        owner: &'a Dependency,
        ty: &TypeExpr,
    ) -> Result<String> {
        match ty {
            TypeExpr::Bool => Ok("boolean".to_string()),
            TypeExpr::U64 | TypeExpr::S64 => Ok("bigint".to_string()),
            TypeExpr::String => Ok("string".to_string()),
            TypeExpr::U8
            | TypeExpr::U16
            | TypeExpr::U32
            | TypeExpr::S8
            | TypeExpr::S16
            | TypeExpr::S32
            | TypeExpr::F32
            | TypeExpr::F64
            | TypeExpr::Char => Ok("number".to_string()),
            TypeExpr::List(element) | TypeExpr::FixedLengthList(element, _)
                if self.ctx.model.resolves_to_u8_in(Some(owner), element) =>
            {
                Ok("Uint8Array".to_string())
            }
            TypeExpr::List(element) | TypeExpr::FixedLengthList(element, _) => {
                let name = format!(
                    "WitforgeListOf{}",
                    self.owner_shape_name_ty(Some(owner), element)?
                );
                self.dep_proto_type_ref(owner, &name)
            }
            TypeExpr::Map(key, value) => {
                let name = format!(
                    "WitforgeMapOf{}And{}",
                    self.owner_shape_name_ty(Some(owner), key)?,
                    self.owner_shape_name_ty(Some(owner), value)?
                );
                self.dep_proto_type_ref(owner, &name)
            }
            TypeExpr::Option(payload) => {
                let name = format!(
                    "WitforgeOptionOf{}",
                    self.owner_shape_name_ty(Some(owner), payload)?
                );
                self.dep_proto_type_ref(owner, &name)
            }
            TypeExpr::Result(result) => {
                let name = format!(
                    "Witforge{}",
                    self.owner_result_shape_name(Some(owner), result)?
                );
                self.dep_proto_type_ref(owner, &name)
            }
            TypeExpr::Named(name) => {
                let (target_dep, def) = self.resolve_type_def(Some(owner), name)?;
                if self.is_same_package(Some(owner), target_dep) {
                    match &def.kind {
                        TypeDefKind::Alias(target) => {
                            self.dependency_defined_proto_singular(owner, target)
                        }
                        TypeDefKind::Record(_)
                        | TypeDefKind::Variant(_)
                        | TypeDefKind::Flags(_)
                        | TypeDefKind::Result(_)
                        | TypeDefKind::Enum(_) => {
                            let proto_name =
                                ident::proto_type_name(name.interface_name(), &name.name);
                            self.dep_proto_type_ref(owner, &proto_name)
                        }
                        TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _)
                            if self.ctx.model.resolves_to_u8_in(Some(owner), element) =>
                        {
                            Ok("Uint8Array".to_string())
                        }
                        TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _) => {
                            let wrapper = format!(
                                "WitforgeListOf{}",
                                self.owner_shape_name_ty(Some(owner), element)?
                            );
                            self.dep_proto_type_ref(owner, &wrapper)
                        }
                        TypeDefKind::Map(key, value) => {
                            let wrapper = format!(
                                "WitforgeMapOf{}And{}",
                                self.owner_shape_name_ty(Some(owner), key)?,
                                self.owner_shape_name_ty(Some(owner), value)?
                            );
                            self.dep_proto_type_ref(owner, &wrapper)
                        }
                        TypeDefKind::Option(payload) => {
                            let wrapper = if matches!(
                                self.foreign_form_expr(Some(owner), payload)?,
                                Form::List | Form::Map | Form::Option
                            ) {
                                format!(
                                    "WitforgeOptionOf{}",
                                    ident::proto_type_name(name.interface_name(), &name.name)
                                )
                            } else {
                                format!(
                                    "WitforgeOptionOf{}",
                                    self.owner_shape_name_ty(Some(owner), payload)?
                                )
                            };
                            self.dep_proto_type_ref(owner, &wrapper)
                        }
                    }
                } else {
                    let other = target_dep.context("foreign type has no dependency context")?;
                    match &def.kind {
                        TypeDefKind::Alias(target) => {
                            let qualified = qualify_type(Some(other), target);
                            self.dependency_defined_proto_singular(owner, &qualified)
                        }
                        TypeDefKind::Record(_)
                        | TypeDefKind::Variant(_)
                        | TypeDefKind::Flags(_)
                        | TypeDefKind::Result(_)
                        | TypeDefKind::Enum(_) => {
                            let proto_name =
                                ident::proto_type_name(name.interface_name(), &name.name);
                            self.dep_proto_type_ref(other, &proto_name)
                        }
                        TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _)
                            if self.ctx.model.resolves_to_u8_in(Some(other), element) =>
                        {
                            Ok("Uint8Array".to_string())
                        }
                        TypeDefKind::List(_)
                        | TypeDefKind::FixedLengthList(_, _)
                        | TypeDefKind::Map(_, _)
                        | TypeDefKind::Option(_) => {
                            let shape = self.foreign_shape_name_for_caller(
                                Some(owner),
                                other,
                                name,
                                &def.kind,
                            )?;
                            let wrapper = format!("Witforge{shape}");
                            self.dep_proto_type_ref(owner, &wrapper)
                        }
                    }
                }
            }
        }
    }

    fn foreign_proto_singular_type(&mut self, name: &QualifiedName) -> Result<String> {
        let (owner, def) = self
            .foreign_type_def(None, name)?
            .context("foreign type needs a dependency package")?;
        match &def.kind {
            TypeDefKind::Alias(target) => {
                let qualified = qualify_type(Some(owner), target);
                self.proto_singular_type(&qualified)
            }
            TypeDefKind::Record(_)
            | TypeDefKind::Variant(_)
            | TypeDefKind::Flags(_)
            | TypeDefKind::Result(_)
            | TypeDefKind::Enum(_) => {
                let proto_name = ident::proto_type_name(name.interface_name(), &name.name);
                self.dep_proto_type_ref(owner, &proto_name)
            }
            TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _)
                if self.ctx.model.resolves_to_u8_in(Some(owner), element) =>
            {
                Ok("Uint8Array".to_string())
            }
            TypeDefKind::List(_)
            | TypeDefKind::FixedLengthList(_, _)
            | TypeDefKind::Map(_, _)
            | TypeDefKind::Option(_) => {
                let shape = self.foreign_shape_name_for_caller(None, owner, name, &def.kind)?;
                Ok(self.local_proto_type_ref(&format!("Witforge{shape}")))
            }
        }
    }

    // --- Glue target reference (same interface, sibling interface, or dep package) ---

    fn glue_target_expr(&mut self, name: &QualifiedName) -> Result<String> {
        let member = ts_value_ident(&name.name, "type glue")?;
        if let Some((ns, pkg)) = name.package() {
            let seg = safe_pkg_segment(ns, pkg)?;
            let iface_stem = safe_interface_file_stem(name.interface_name())?;
            let target_scoped = self.ctx.dep_layout.is_scoped(ns, pkg);
            let spec = if self.ctx.dep_context.is_none() {
                if target_scoped {
                    format!(
                        "../witforge_deps/{}/{seg}/{iface_stem}.js",
                        polyglot::major_dir_name(self.ctx.root_major)
                    )
                } else {
                    format!("../witforge_deps/{seg}/{iface_stem}.js")
                }
            } else if self.ctx.dep_scoped {
                if target_scoped {
                    format!("../{seg}/{iface_stem}.js")
                } else {
                    format!("../../{seg}/{iface_stem}.js")
                }
            } else {
                format!("../{seg}/{iface_stem}.js")
            };
            let alias = self
                .imports
                .glue_value_alias(spec, &format!("_wf_d_{seg}_{iface_stem}"));
            return Ok(format!("{alias}.{member}"));
        }
        if name.interface == self.interface.name {
            return Ok(member);
        }
        let stem = self
            .local_stems
            .get(name.interface.as_str())
            .copied()
            .map(str::to_string)
            .map_or_else(|| safe_interface_file_stem(&name.interface), Ok)?;
        let alias = self
            .imports
            .glue_value_alias(format!("./{stem}.js"), &format!("_wf_g_{stem}"));
        Ok(format!("{alias}.{member}"))
    }

    // --- Type definition emission ---

    fn emit_type(&mut self, out: &mut String, def: &TypeDef) -> Result<()> {
        let export_ident = ts_value_ident(&def.name, "type glue")?;
        let plain = self.plain_named_type(&QualifiedName {
            interface: self.interface.name.clone(),
            name: def.name.clone(),
        })?;
        let fallback = format!(
            "Checked protobuf glue for `{}/{}`.",
            self.interface.name, def.name
        );
        write_jsdoc(out, 0, &def.docs, &def.stability, Some(&fallback))?;
        match &def.kind {
            TypeDefKind::Record(fields) => {
                self.emit_record(out, &export_ident, &plain, &def.name, fields)?;
            }
            TypeDefKind::Variant(cases) => {
                self.emit_variant(out, &export_ident, &plain, &def.name, cases)?;
            }
            TypeDefKind::Enum(cases) => {
                self.emit_enum(out, &export_ident, &plain, &def.name, cases)?;
            }
            TypeDefKind::Flags(flags) => {
                self.emit_flags(out, &export_ident, &plain, &def.name, flags)?;
            }
            TypeDefKind::Result(result) => {
                self.emit_result(out, &export_ident, &plain, &def.name, result)?;
            }
            TypeDefKind::Alias(target) => {
                self.emit_alias(out, &export_ident, &plain, &def.name, target)?;
            }
            TypeDefKind::List(element) => {
                self.emit_list(out, &export_ident, &plain, &def.name, element)?;
            }
            TypeDefKind::FixedLengthList(element, len) => {
                self.emit_fixed_list(out, &export_ident, &plain, &def.name, element, *len)?;
            }
            TypeDefKind::Map(key, value) => {
                self.emit_map(out, &export_ident, &plain, &def.name, key, value)?;
            }
            TypeDefKind::Option(payload) => {
                self.emit_option(out, &export_ident, &plain, &def.name, payload)?;
            }
        }
        Ok(())
    }

    #[allow(clippy::too_many_lines)]
    fn emit_record(
        &mut self,
        out: &mut String,
        export_ident: &str,
        plain: &str,
        type_name: &str,
        fields: &[Field],
    ) -> Result<()> {
        let proto_name = ident::proto_type_name(&self.interface.name, type_name);
        let proto_ty = self.local_proto_type_ref(&proto_name);
        let proto_schema = self.local_proto_schema_ref(&proto_name);
        self.imports.use_create();

        writeln!(out, "export const {export_ident} = {{")?;
        writeln!(out, "  schema: {proto_schema},")?;

        if fields.is_empty() {
            writeln!(out, "  toProto(_value: {plain}): {proto_ty} {{")?;
            writeln!(out, "    return _wf_create({proto_schema});")?;
            writeln!(out, "  }},")?;
            writeln!(out, "  fromProto(_value: {proto_ty}): {plain} {{")?;
            writeln!(out, "    return {{}};")?;
            writeln!(out, "  }},")?;
            writeln!(out, "}} as const;")?;
            return Ok(());
        }

        // toProto
        writeln!(out, "  toProto(value: {plain}): {proto_ty} {{")?;
        let mut stmts = Vec::new();
        let mut temps = TempGen::new();
        let mut req_assignments = Vec::new();
        let mut opt_assignments = Vec::new();
        for field in fields {
            let ts_field = ts_value_ident(&field.name, "record field")?;
            let es_field = es_field_local_name(&field.name);
            let identity = format!("{}/{type_name}.{}", self.interface.name, field.name);
            let src = format!("value.{ts_field}");
            if self.form(&field.ty)? == Form::Option {
                let encoded =
                    self.emit_encode_value(&mut stmts, 4, &mut temps, &src, &field.ty, &identity)?;
                let opt_var = if encoded.starts_with("_v") {
                    encoded
                } else {
                    let var = temps.fresh();
                    stmts.push(format!("    const {var} = {encoded};"));
                    var
                };
                opt_assignments.push((es_field, opt_var));
            } else {
                let encoded =
                    self.emit_encode_value(&mut stmts, 4, &mut temps, &src, &field.ty, &identity)?;
                req_assignments.push((es_field, encoded));
            }
        }
        for stmt in stmts {
            writeln!(out, "{stmt}")?;
        }
        if opt_assignments.is_empty() {
            writeln!(out, "    return _wf_create({proto_schema}, {{")?;
            for (es_field, expr) in req_assignments {
                writeln!(out, "      {es_field}: {expr},")?;
            }
            writeln!(out, "    }});")?;
        } else {
            writeln!(out, "    const _out = _wf_create({proto_schema}, {{")?;
            for (es_field, expr) in req_assignments {
                writeln!(out, "      {es_field}: {expr},")?;
            }
            writeln!(out, "    }});")?;
            for (es_field, expr) in opt_assignments {
                writeln!(out, "    if ({expr} !== undefined) {{")?;
                writeln!(out, "      _out.{es_field} = {expr};")?;
                writeln!(out, "    }}")?;
            }
            writeln!(out, "    return _out;")?;
        }
        writeln!(out, "  }},")?;

        // fromProto
        writeln!(out, "  fromProto(value: {proto_ty}): {plain} {{")?;
        let mut dec_stmts = Vec::new();
        let mut dec_temps = TempGen::new();
        let mut plain_pairs = Vec::with_capacity(fields.len());
        for field in fields {
            let ts_field = ts_value_ident(&field.name, "record field")?;
            let es_field = es_field_local_name(&field.name);
            let identity = format!("{}/{type_name}.{}", self.interface.name, field.name);
            let decoded = self.emit_decode_field(
                &mut dec_stmts,
                4,
                &mut dec_temps,
                &format!("value.{es_field}"),
                &field.ty,
                &identity,
            )?;
            plain_pairs.push((ts_field, decoded));
        }
        for stmt in dec_stmts {
            writeln!(out, "{stmt}")?;
        }
        writeln!(out, "    return {{")?;
        for (ts_field, expr) in plain_pairs {
            writeln!(out, "      {ts_field}: {expr},")?;
        }
        writeln!(out, "    }};")?;
        writeln!(out, "  }},")?;
        writeln!(out, "}} as const;")?;
        Ok(())
    }

    #[allow(clippy::too_many_lines)]
    fn emit_variant(
        &mut self,
        out: &mut String,
        export_ident: &str,
        plain: &str,
        type_name: &str,
        cases: &[Case],
    ) -> Result<()> {
        let proto_name = ident::proto_type_name(&self.interface.name, type_name);
        let proto_ty = self.local_proto_type_ref(&proto_name);
        let proto_schema = self.local_proto_schema_ref(&proto_name);
        let identity = format!("{}/{type_name}", self.interface.name);
        let identity_lit = escape_ts_string(&identity);
        self.imports.use_error();

        writeln!(out, "export const {export_ident} = {{")?;
        writeln!(out, "  schema: {proto_schema},")?;

        // toProto
        if cases.is_empty() {
            writeln!(out, "  toProto(_value: {plain}): {proto_ty} {{")?;
            writeln!(
                out,
                "    throw new _wf_Error(\"UnknownCase\", {{ message: {identity_lit} }});"
            )?;
            writeln!(out, "  }},")?;
        } else {
            self.imports.use_create();
            writeln!(out, "  toProto(value: {plain}): {proto_ty} {{")?;
            writeln!(out, "    switch (value.tag) {{")?;
            for case in cases {
                let tag_lit = escape_ts_string(&case.name);
                let es_case = escape_ts_string(&es_oneof_case_local_name(&case.name));
                writeln!(out, "      case {tag_lit}: {{")?;
                if let Some(payload) = &case.payload {
                    let mut stmts = Vec::new();
                    let mut temps = TempGen::new();
                    let encoded = self.emit_encode_singular(
                        &mut stmts,
                        8,
                        &mut temps,
                        "value.value",
                        payload,
                        &identity,
                    )?;
                    for stmt in stmts {
                        writeln!(out, "{stmt}")?;
                    }
                    writeln!(
                        out,
                        "        return _wf_create({proto_schema}, {{ witforgeValue: {{ case: {es_case}, value: {encoded} }} }});"
                    )?;
                } else {
                    let empty_schema = self.local_proto_schema_ref("Empty");
                    writeln!(
                        out,
                        "        return _wf_create({proto_schema}, {{ witforgeValue: {{ case: {es_case}, value: _wf_create({empty_schema}) }} }});"
                    )?;
                }
                writeln!(out, "      }}")?;
            }
            writeln!(out, "      default:")?;
            writeln!(
                out,
                "        throw new _wf_Error(\"UnknownCase\", {{ message: {identity_lit} }});"
            )?;
            writeln!(out, "    }}")?;
            writeln!(out, "  }},")?;
        }

        // fromProto
        if cases.is_empty() {
            writeln!(out, "  fromProto(_value: {proto_ty}): {plain} {{")?;
            writeln!(
                out,
                "    throw new _wf_Error(\"UnknownCase\", {{ message: {identity_lit} }});"
            )?;
            writeln!(out, "  }},")?;
        } else {
            writeln!(out, "  fromProto(value: {proto_ty}): {plain} {{")?;
            writeln!(out, "    switch (value.witforgeValue.case) {{")?;
            for case in cases {
                let tag_lit = escape_ts_string(&case.name);
                let es_case = escape_ts_string(&es_oneof_case_local_name(&case.name));
                writeln!(out, "      case {es_case}: {{")?;
                if let Some(payload) = &case.payload {
                    let mut stmts = Vec::new();
                    let mut temps = TempGen::new();
                    let decoded = self.emit_decode_singular(
                        &mut stmts,
                        8,
                        &mut temps,
                        "value.witforgeValue.value",
                        payload,
                        &identity,
                    )?;
                    for stmt in stmts {
                        writeln!(out, "{stmt}")?;
                    }
                    writeln!(
                        out,
                        "        return {{ tag: {tag_lit}, value: {decoded} }};"
                    )?;
                } else {
                    writeln!(out, "        return {{ tag: {tag_lit} }};")?;
                }
                writeln!(out, "      }}")?;
            }
            writeln!(out, "      default:")?;
            writeln!(
                out,
                "        throw new _wf_Error(\"UnknownCase\", {{ message: {identity_lit} }});"
            )?;
            writeln!(out, "    }}")?;
            writeln!(out, "  }},")?;
        }
        writeln!(out, "}} as const;")?;
        Ok(())
    }

    fn emit_enum(
        &mut self,
        out: &mut String,
        export_ident: &str,
        plain: &str,
        type_name: &str,
        cases: &[Case],
    ) -> Result<()> {
        let proto_enum = ident::proto_type_name(&self.interface.name, type_name);
        let proto_ty = self.local_proto_type_ref(&proto_enum);
        let identity = format!("{}/{type_name}", self.interface.name);
        let identity_lit = escape_ts_string(&identity);
        self.imports.use_error();

        writeln!(out, "export const {export_ident} = {{")?;
        writeln!(out, "  toProto(value: {plain}): {proto_ty} {{")?;
        writeln!(out, "    switch (value) {{")?;
        for case in cases {
            let tag_lit = escape_ts_string(&case.name);
            let proto_val = ident::proto_enum_value_name(&proto_enum, &case.name);
            let es_ref = self.local_proto_enum_value_ref(&proto_enum, &proto_val);
            writeln!(out, "      case {tag_lit}:")?;
            writeln!(out, "        return {es_ref};")?;
        }
        writeln!(out, "      default:")?;
        writeln!(
            out,
            "        throw new _wf_Error(\"UnknownEnumValue\", {{ enumeration: {identity_lit}, value: typeof value === \"number\" ? value : String(value) }});"
        )?;
        writeln!(out, "    }}")?;
        writeln!(out, "  }},")?;

        writeln!(out, "  fromProto(value: {proto_ty}): {plain} {{")?;
        writeln!(out, "    switch (value) {{")?;
        for case in cases {
            let number = self.number(&self.interface.name, type_name, &case.name)?;
            let tag_lit = escape_ts_string(&case.name);
            writeln!(out, "      case {number}:")?;
            writeln!(out, "        return {tag_lit};")?;
        }
        writeln!(out, "      default:")?;
        writeln!(
            out,
            "        throw new _wf_Error(\"UnknownEnumValue\", {{ enumeration: {identity_lit}, value }});"
        )?;
        writeln!(out, "    }}")?;
        writeln!(out, "  }},")?;
        writeln!(out, "}} as const;")?;
        Ok(())
    }

    fn emit_flags(
        &mut self,
        out: &mut String,
        export_ident: &str,
        plain: &str,
        type_name: &str,
        flags: &[Flag],
    ) -> Result<()> {
        let proto_name = ident::proto_type_name(&self.interface.name, type_name);
        let proto_ty = self.local_proto_type_ref(&proto_name);
        let proto_schema = self.local_proto_schema_ref(&proto_name);
        self.imports.use_create();

        writeln!(out, "export const {export_ident} = {{")?;
        writeln!(out, "  schema: {proto_schema},")?;
        if flags.is_empty() {
            writeln!(out, "  toProto(_value: {plain}): {proto_ty} {{")?;
            writeln!(out, "    return _wf_create({proto_schema});")?;
            writeln!(out, "  }},")?;
            writeln!(out, "  fromProto(_value: {proto_ty}): {plain} {{")?;
            writeln!(out, "    return {{}};")?;
            writeln!(out, "  }},")?;
            writeln!(out, "}} as const;")?;
            return Ok(());
        }

        writeln!(out, "  toProto(value: {plain}): {proto_ty} {{")?;
        writeln!(out, "    return _wf_create({proto_schema}, {{")?;
        for flag in flags {
            let ts_flag = ts_value_ident(&flag.name, "flag")?;
            let es_flag = es_field_local_name(&flag.name);
            writeln!(out, "      {es_flag}: value.{ts_flag},")?;
        }
        writeln!(out, "    }});")?;
        writeln!(out, "  }},")?;

        writeln!(out, "  fromProto(value: {proto_ty}): {plain} {{")?;
        writeln!(out, "    return {{")?;
        for flag in flags {
            let ts_flag = ts_value_ident(&flag.name, "flag")?;
            let es_flag = es_field_local_name(&flag.name);
            writeln!(out, "      {ts_flag}: value.{es_flag},")?;
        }
        writeln!(out, "    }};")?;
        writeln!(out, "  }},")?;
        writeln!(out, "}} as const;")?;
        Ok(())
    }

    #[allow(clippy::too_many_lines)]
    fn emit_result(
        &mut self,
        out: &mut String,
        export_ident: &str,
        plain: &str,
        type_name: &str,
        result: &ResultExpr,
    ) -> Result<()> {
        let proto_name = ident::proto_type_name(&self.interface.name, type_name);
        let proto_ty = self.local_proto_type_ref(&proto_name);
        let proto_schema = self.local_proto_schema_ref(&proto_name);
        let identity = format!("{}/{type_name}", self.interface.name);
        let identity_lit = escape_ts_string(&identity);
        self.imports.use_create();
        self.imports.use_error();

        writeln!(out, "export const {export_ident} = {{")?;
        writeln!(out, "  schema: {proto_schema},")?;

        // toProto
        writeln!(out, "  toProto(value: {plain}): {proto_ty} {{")?;
        writeln!(out, "    switch (value.tag) {{")?;
        writeln!(out, "      case \"ok\": {{")?;
        if let Some(ok_ty) = &result.ok {
            let mut stmts = Vec::new();
            let mut temps = TempGen::new();
            let encoded = self.emit_encode_singular(
                &mut stmts,
                8,
                &mut temps,
                "value.value",
                ok_ty,
                &identity,
            )?;
            for stmt in stmts {
                writeln!(out, "{stmt}")?;
            }
            writeln!(
                out,
                "        return _wf_create({proto_schema}, {{ value: {{ case: \"ok\", value: {encoded} }} }});"
            )?;
        } else {
            let empty_schema = self.local_proto_schema_ref("Empty");
            writeln!(
                out,
                "        return _wf_create({proto_schema}, {{ value: {{ case: \"ok\", value: _wf_create({empty_schema}) }} }});"
            )?;
        }
        writeln!(out, "      }}")?;
        writeln!(out, "      case \"err\": {{")?;
        if let Some(err_ty) = &result.err {
            let mut stmts = Vec::new();
            let mut temps = TempGen::new();
            let encoded = self.emit_encode_singular(
                &mut stmts,
                8,
                &mut temps,
                "value.error",
                err_ty,
                &identity,
            )?;
            for stmt in stmts {
                writeln!(out, "{stmt}")?;
            }
            writeln!(
                out,
                "        return _wf_create({proto_schema}, {{ value: {{ case: \"err\", value: {encoded} }} }});"
            )?;
        } else {
            let empty_schema = self.local_proto_schema_ref("Empty");
            writeln!(
                out,
                "        return _wf_create({proto_schema}, {{ value: {{ case: \"err\", value: _wf_create({empty_schema}) }} }});"
            )?;
        }
        writeln!(out, "      }}")?;
        writeln!(out, "      default:")?;
        writeln!(
            out,
            "        throw new _wf_Error(\"UnknownCase\", {{ message: {identity_lit} }});"
        )?;
        writeln!(out, "    }}")?;
        writeln!(out, "  }},")?;

        // fromProto
        writeln!(out, "  fromProto(value: {proto_ty}): {plain} {{")?;
        writeln!(out, "    switch (value.value.case) {{")?;
        writeln!(out, "      case \"ok\": {{")?;
        if let Some(ok_ty) = &result.ok {
            let mut stmts = Vec::new();
            let mut temps = TempGen::new();
            let decoded = self.emit_decode_singular(
                &mut stmts,
                8,
                &mut temps,
                "value.value.value",
                ok_ty,
                &identity,
            )?;
            for stmt in stmts {
                writeln!(out, "{stmt}")?;
            }
            writeln!(out, "        return {{ tag: \"ok\", value: {decoded} }};")?;
        } else {
            writeln!(out, "        return {{ tag: \"ok\" }};")?;
        }
        writeln!(out, "      }}")?;
        writeln!(out, "      case \"err\": {{")?;
        if let Some(err_ty) = &result.err {
            let mut stmts = Vec::new();
            let mut temps = TempGen::new();
            let decoded = self.emit_decode_singular(
                &mut stmts,
                8,
                &mut temps,
                "value.value.value",
                err_ty,
                &identity,
            )?;
            for stmt in stmts {
                writeln!(out, "{stmt}")?;
            }
            writeln!(out, "        return {{ tag: \"err\", error: {decoded} }};")?;
        } else {
            writeln!(out, "        return {{ tag: \"err\" }};")?;
        }
        writeln!(out, "      }}")?;
        writeln!(out, "      default:")?;
        writeln!(
            out,
            "        throw new _wf_Error(\"UnknownCase\", {{ message: {identity_lit} }});"
        )?;
        writeln!(out, "    }}")?;
        writeln!(out, "  }},")?;
        writeln!(out, "}} as const;")?;
        Ok(())
    }

    fn emit_alias(
        &mut self,
        out: &mut String,
        export_ident: &str,
        plain: &str,
        type_name: &str,
        target: &TypeExpr,
    ) -> Result<()> {
        let proto_ty = self.proto_direct_type(target)?;
        let identity = format!("{}/{type_name}", self.interface.name);
        writeln!(out, "export const {export_ident} = {{")?;

        if let TypeExpr::Named(target_name) = target {
            let target_ref = self.glue_target_expr(target_name)?;
            writeln!(out, "  toProto(value: {plain}): {proto_ty} {{")?;
            writeln!(out, "    return {target_ref}.toProto(value);")?;
            writeln!(out, "  }},")?;
            writeln!(out, "  fromProto(value: {proto_ty}): {plain} {{")?;
            writeln!(out, "    return {target_ref}.fromProto(value);")?;
            writeln!(out, "  }},")?;
            writeln!(out, "}} as const;")?;
            return Ok(());
        }

        writeln!(out, "  toProto(value: {plain}): {proto_ty} {{")?;
        let mut stmts = Vec::new();
        let mut temps = TempGen::new();
        let encoded =
            self.emit_encode_value(&mut stmts, 4, &mut temps, "value", target, &identity)?;
        for stmt in stmts {
            writeln!(out, "{stmt}")?;
        }
        writeln!(out, "    return {encoded};")?;
        writeln!(out, "  }},")?;

        writeln!(out, "  fromProto(value: {proto_ty}): {plain} {{")?;
        let mut dec_stmts = Vec::new();
        let mut dec_temps = TempGen::new();
        let decoded = self.emit_decode_value(
            &mut dec_stmts,
            4,
            &mut dec_temps,
            "value",
            target,
            &identity,
        )?;
        for stmt in dec_stmts {
            writeln!(out, "{stmt}")?;
        }
        writeln!(out, "    return {decoded};")?;
        writeln!(out, "  }},")?;
        writeln!(out, "}} as const;")?;
        Ok(())
    }

    fn emit_list(
        &mut self,
        out: &mut String,
        export_ident: &str,
        plain: &str,
        type_name: &str,
        element: &TypeExpr,
    ) -> Result<()> {
        let list_ty = TypeExpr::List(Box::new(element.clone()));
        let proto_ty = self.proto_direct_type(&list_ty)?;
        let identity = format!("{}/{type_name}", self.interface.name);
        writeln!(out, "export const {export_ident} = {{")?;

        writeln!(out, "  toProto(value: {plain}): {proto_ty} {{")?;
        let mut stmts = Vec::new();
        let mut temps = TempGen::new();
        let encoded =
            self.emit_encode_value(&mut stmts, 4, &mut temps, "value", &list_ty, &identity)?;
        for stmt in stmts {
            writeln!(out, "{stmt}")?;
        }
        writeln!(out, "    return {encoded};")?;
        writeln!(out, "  }},")?;

        writeln!(out, "  fromProto(value: {proto_ty}): {plain} {{")?;
        let mut dec_stmts = Vec::new();
        let mut dec_temps = TempGen::new();
        let decoded = self.emit_decode_value(
            &mut dec_stmts,
            4,
            &mut dec_temps,
            "value",
            &list_ty,
            &identity,
        )?;
        for stmt in dec_stmts {
            writeln!(out, "{stmt}")?;
        }
        writeln!(out, "    return {decoded};")?;
        writeln!(out, "  }},")?;
        writeln!(out, "}} as const;")?;
        Ok(())
    }

    fn emit_fixed_list(
        &mut self,
        out: &mut String,
        export_ident: &str,
        plain: &str,
        type_name: &str,
        element: &TypeExpr,
        len: u32,
    ) -> Result<()> {
        let list_ty = TypeExpr::FixedLengthList(Box::new(element.clone()), len);
        let proto_ty = self.proto_direct_type(&list_ty)?;
        let identity = format!("{}/{type_name}", self.interface.name);
        writeln!(out, "export const {export_ident} = {{")?;

        writeln!(out, "  toProto(value: {plain}): {proto_ty} {{")?;
        let mut stmts = Vec::new();
        let mut temps = TempGen::new();
        let encoded =
            self.emit_encode_value(&mut stmts, 4, &mut temps, "value", &list_ty, &identity)?;
        for stmt in stmts {
            writeln!(out, "{stmt}")?;
        }
        writeln!(out, "    return {encoded};")?;
        writeln!(out, "  }},")?;

        writeln!(out, "  fromProto(value: {proto_ty}): {plain} {{")?;
        let mut dec_stmts = Vec::new();
        let mut dec_temps = TempGen::new();
        let decoded = self.emit_decode_value(
            &mut dec_stmts,
            4,
            &mut dec_temps,
            "value",
            &list_ty,
            &identity,
        )?;
        for stmt in dec_stmts {
            writeln!(out, "{stmt}")?;
        }
        writeln!(out, "    return {decoded};")?;
        writeln!(out, "  }},")?;
        writeln!(out, "}} as const;")?;
        Ok(())
    }

    fn emit_map(
        &mut self,
        out: &mut String,
        export_ident: &str,
        plain: &str,
        type_name: &str,
        key: &TypeExpr,
        value: &TypeExpr,
    ) -> Result<()> {
        let map_ty = TypeExpr::Map(Box::new(key.clone()), Box::new(value.clone()));
        let proto_ty = self.proto_direct_type(&map_ty)?;
        let identity = format!("{}/{type_name}", self.interface.name);
        writeln!(out, "export const {export_ident} = {{")?;

        writeln!(out, "  toProto(value: {plain}): {proto_ty} {{")?;
        let mut stmts = Vec::new();
        let mut temps = TempGen::new();
        let encoded =
            self.emit_encode_value(&mut stmts, 4, &mut temps, "value", &map_ty, &identity)?;
        for stmt in stmts {
            writeln!(out, "{stmt}")?;
        }
        writeln!(out, "    return {encoded};")?;
        writeln!(out, "  }},")?;

        writeln!(out, "  fromProto(value: {proto_ty}): {plain} {{")?;
        let mut dec_stmts = Vec::new();
        let mut dec_temps = TempGen::new();
        let decoded = self.emit_decode_value(
            &mut dec_stmts,
            4,
            &mut dec_temps,
            "value",
            &map_ty,
            &identity,
        )?;
        for stmt in dec_stmts {
            writeln!(out, "{stmt}")?;
        }
        writeln!(out, "    return {decoded};")?;
        writeln!(out, "  }},")?;
        writeln!(out, "}} as const;")?;
        Ok(())
    }

    #[allow(clippy::too_many_lines)]
    fn emit_option(
        &mut self,
        out: &mut String,
        export_ident: &str,
        plain: &str,
        type_name: &str,
        payload: &TypeExpr,
    ) -> Result<()> {
        let qualified = QualifiedName {
            interface: self.interface.name.clone(),
            name: type_name.to_string(),
        };
        let proto_ty = self.proto_direct_type(&TypeExpr::Named(qualified))?;
        let identity = format!("{}/{type_name}", self.interface.name);
        let identity_lit = escape_ts_string(&identity);
        let form = self.form(payload)?;
        let proto_wrapper_name = ident::proto_type_name(&self.interface.name, type_name);

        writeln!(out, "export const {export_ident} = {{")?;
        match form {
            Form::List => {
                let wrapper_schema = self.local_proto_schema_ref(&proto_wrapper_name);
                self.imports.use_create();
                self.imports.use_error();
                self.imports.use_none();
                self.imports.use_some();

                writeln!(out, "  toProto(value: {plain}): {proto_ty} {{")?;
                writeln!(out, "    if (value.tag === \"none\") {{")?;
                writeln!(out, "      return undefined;")?;
                writeln!(out, "    }}")?;
                writeln!(out, "    if (value.tag !== \"some\") {{")?;
                writeln!(
                    out,
                    "      throw new _wf_Error(\"InvalidState\", {{ message: {identity_lit} }});"
                )?;
                writeln!(out, "    }}")?;
                let mut stmts = Vec::new();
                let mut temps = TempGen::new();
                let values = if let Some((
                    _,
                    foreign_name,
                    TypeDefKind::List(_) | TypeDefKind::FixedLengthList(_, _),
                )) = self.resolve_foreign_named(payload)?
                {
                    let target = self.glue_target_expr(&foreign_name)?;
                    format!("{target}.toProto(value.value)")
                } else {
                    let (elem, fixed_len) = self.list_info(payload)?;
                    let list_expr = match fixed_len {
                        Some(len) => TypeExpr::FixedLengthList(Box::new(elem), len),
                        None => TypeExpr::List(Box::new(elem)),
                    };
                    self.emit_encode_value(
                        &mut stmts,
                        4,
                        &mut temps,
                        "value.value",
                        &list_expr,
                        &identity,
                    )?
                };
                for stmt in stmts {
                    writeln!(out, "{stmt}")?;
                }
                writeln!(
                    out,
                    "    return _wf_create({wrapper_schema}, {{ values: {values} }});"
                )?;
                writeln!(out, "  }},")?;

                writeln!(out, "  fromProto(value: {proto_ty}): {plain} {{")?;
                writeln!(out, "    if (value === undefined) {{")?;
                writeln!(out, "      return _wf_NONE;")?;
                writeln!(out, "    }}")?;
                let mut dec_stmts = Vec::new();
                let mut dec_temps = TempGen::new();
                let decoded = if let Some((
                    _,
                    foreign_name,
                    TypeDefKind::List(_) | TypeDefKind::FixedLengthList(_, _),
                )) = self.resolve_foreign_named(payload)?
                {
                    let target = self.glue_target_expr(&foreign_name)?;
                    format!("{target}.fromProto(value.values)")
                } else {
                    let (elem, fixed_len) = self.list_info(payload)?;
                    let list_expr = match fixed_len {
                        Some(len) => TypeExpr::FixedLengthList(Box::new(elem), len),
                        None => TypeExpr::List(Box::new(elem)),
                    };
                    self.emit_decode_value(
                        &mut dec_stmts,
                        4,
                        &mut dec_temps,
                        "value.values",
                        &list_expr,
                        &identity,
                    )?
                };
                for stmt in dec_stmts {
                    writeln!(out, "{stmt}")?;
                }
                writeln!(out, "    return _wf_some({decoded});")?;
                writeln!(out, "  }},")?;
            }
            Form::Map => {
                let wrapper_schema = self.local_proto_schema_ref(&proto_wrapper_name);
                self.imports.use_create();
                self.imports.use_error();
                self.imports.use_none();
                self.imports.use_some();

                writeln!(out, "  toProto(value: {plain}): {proto_ty} {{")?;
                writeln!(out, "    if (value.tag === \"none\") {{")?;
                writeln!(out, "      return undefined;")?;
                writeln!(out, "    }}")?;
                writeln!(out, "    if (value.tag !== \"some\") {{")?;
                writeln!(
                    out,
                    "      throw new _wf_Error(\"InvalidState\", {{ message: {identity_lit} }});"
                )?;
                writeln!(out, "    }}")?;
                let mut stmts = Vec::new();
                let mut temps = TempGen::new();
                let entries = if let Some((_, foreign_name, TypeDefKind::Map(_, _))) =
                    self.resolve_foreign_named(payload)?
                {
                    let target = self.glue_target_expr(&foreign_name)?;
                    format!("{target}.toProto(value.value)")
                } else {
                    let (k, v) = self.map_types(payload)?;
                    let map_expr = TypeExpr::Map(Box::new(k), Box::new(v));
                    self.emit_encode_value(
                        &mut stmts,
                        4,
                        &mut temps,
                        "value.value",
                        &map_expr,
                        &identity,
                    )?
                };
                for stmt in stmts {
                    writeln!(out, "{stmt}")?;
                }
                writeln!(
                    out,
                    "    return _wf_create({wrapper_schema}, {{ entries: {entries} }});"
                )?;
                writeln!(out, "  }},")?;

                writeln!(out, "  fromProto(value: {proto_ty}): {plain} {{")?;
                writeln!(out, "    if (value === undefined) {{")?;
                writeln!(out, "      return _wf_NONE;")?;
                writeln!(out, "    }}")?;
                let mut dec_stmts = Vec::new();
                let mut dec_temps = TempGen::new();
                let decoded = if let Some((_, foreign_name, TypeDefKind::Map(_, _))) =
                    self.resolve_foreign_named(payload)?
                {
                    let target = self.glue_target_expr(&foreign_name)?;
                    format!("{target}.fromProto(value.entries)")
                } else {
                    let (k, v) = self.map_types(payload)?;
                    let map_expr = TypeExpr::Map(Box::new(k), Box::new(v));
                    self.emit_decode_value(
                        &mut dec_stmts,
                        4,
                        &mut dec_temps,
                        "value.entries",
                        &map_expr,
                        &identity,
                    )?
                };
                for stmt in dec_stmts {
                    writeln!(out, "{stmt}")?;
                }
                writeln!(out, "    return _wf_some({decoded});")?;
                writeln!(out, "  }},")?;
            }
            Form::Option => {
                let wrapper_schema = self.local_proto_schema_ref(&proto_wrapper_name);
                let empty_schema = self.local_proto_schema_ref("Empty");
                self.imports.use_create();
                self.imports.use_error();
                self.imports.use_none();
                self.imports.use_some();

                writeln!(out, "  toProto(value: {plain}): {proto_ty} {{")?;
                writeln!(out, "    if (value.tag === \"none\") {{")?;
                writeln!(out, "      return undefined;")?;
                writeln!(out, "    }}")?;
                writeln!(out, "    if (value.tag !== \"some\") {{")?;
                writeln!(
                    out,
                    "      throw new _wf_Error(\"InvalidState\", {{ message: {identity_lit} }});"
                )?;
                writeln!(out, "    }}")?;
                if let Some((_, foreign_name, TypeDefKind::Option(_))) =
                    self.resolve_foreign_named(payload)?
                {
                    let target = self.glue_target_expr(&foreign_name)?;
                    writeln!(out, "    const _inner = {target}.toProto(value.value);")?;
                    writeln!(
                        out,
                        "    return _wf_create({wrapper_schema}, {{ value: _inner === undefined ? {{ case: \"none\", value: _wf_create({empty_schema}) }} : {{ case: \"some\", value: _inner }} }});"
                    )?;
                } else {
                    let inner_payload = self.option_payload(payload)?;
                    writeln!(out, "    if (value.value.tag === \"none\") {{")?;
                    writeln!(
                        out,
                        "      return _wf_create({wrapper_schema}, {{ value: {{ case: \"none\", value: _wf_create({empty_schema}) }} }});"
                    )?;
                    writeln!(out, "    }}")?;
                    writeln!(out, "    if (value.value.tag !== \"some\") {{")?;
                    writeln!(
                        out,
                        "      throw new _wf_Error(\"InvalidState\", {{ message: {identity_lit} }});"
                    )?;
                    writeln!(out, "    }}")?;
                    let mut stmts = Vec::new();
                    let mut temps = TempGen::new();
                    let encoded = self.emit_encode_singular(
                        &mut stmts,
                        4,
                        &mut temps,
                        "value.value.value",
                        &inner_payload,
                        &identity,
                    )?;
                    for stmt in stmts {
                        writeln!(out, "{stmt}")?;
                    }
                    writeln!(
                        out,
                        "    return _wf_create({wrapper_schema}, {{ value: {{ case: \"some\", value: {encoded} }} }});"
                    )?;
                }
                writeln!(out, "  }},")?;

                writeln!(out, "  fromProto(value: {proto_ty}): {plain} {{")?;
                writeln!(out, "    if (value === undefined) {{")?;
                writeln!(out, "      return _wf_NONE;")?;
                writeln!(out, "    }}")?;
                writeln!(out, "    switch (value.value.case) {{")?;
                writeln!(out, "      case \"none\":")?;
                writeln!(out, "        return _wf_some(_wf_NONE);")?;
                writeln!(out, "      case \"some\": {{")?;
                if let Some((_, foreign_name, TypeDefKind::Option(_))) =
                    self.resolve_foreign_named(payload)?
                {
                    let target = self.glue_target_expr(&foreign_name)?;
                    writeln!(
                        out,
                        "        return _wf_some({target}.fromProto(value.value.value));"
                    )?;
                } else {
                    let inner_payload = self.option_payload(payload)?;
                    let mut dec_stmts = Vec::new();
                    let mut dec_temps = TempGen::new();
                    let decoded = self.emit_decode_singular(
                        &mut dec_stmts,
                        8,
                        &mut dec_temps,
                        "value.value.value",
                        &inner_payload,
                        &identity,
                    )?;
                    for stmt in dec_stmts {
                        writeln!(out, "{stmt}")?;
                    }
                    writeln!(out, "        return _wf_some(_wf_some({decoded}));")?;
                }
                writeln!(out, "      }}")?;
                writeln!(out, "      default:")?;
                writeln!(
                    out,
                    "        throw new _wf_Error(\"InvalidState\", {{ message: {identity_lit} }});"
                )?;
                writeln!(out, "    }}")?;
                writeln!(out, "  }},")?;
            }
            Form::Scalar | Form::Bytes | Form::Enum | Form::Message => {
                self.imports.use_error();
                self.imports.use_none();
                self.imports.use_some();

                writeln!(out, "  toProto(value: {plain}): {proto_ty} {{")?;
                writeln!(out, "    if (value.tag === \"none\") {{")?;
                writeln!(out, "      return undefined;")?;
                writeln!(out, "    }}")?;
                writeln!(out, "    if (value.tag !== \"some\") {{")?;
                writeln!(
                    out,
                    "      throw new _wf_Error(\"InvalidState\", {{ message: {identity_lit} }});"
                )?;
                writeln!(out, "    }}")?;
                let mut stmts = Vec::new();
                let mut temps = TempGen::new();
                let encoded = self.emit_encode_singular(
                    &mut stmts,
                    4,
                    &mut temps,
                    "value.value",
                    payload,
                    &identity,
                )?;
                for stmt in stmts {
                    writeln!(out, "{stmt}")?;
                }
                writeln!(out, "    return {encoded};")?;
                writeln!(out, "  }},")?;

                writeln!(out, "  fromProto(value: {proto_ty}): {plain} {{")?;
                writeln!(out, "    if (value === undefined) {{")?;
                writeln!(out, "      return _wf_NONE;")?;
                writeln!(out, "    }}")?;
                let mut dec_stmts = Vec::new();
                let mut dec_temps = TempGen::new();
                let decoded = self.emit_decode_singular(
                    &mut dec_stmts,
                    4,
                    &mut dec_temps,
                    "value",
                    payload,
                    &identity,
                )?;
                for stmt in dec_stmts {
                    writeln!(out, "{stmt}")?;
                }
                writeln!(out, "    return _wf_some({decoded});")?;
                writeln!(out, "  }},")?;
            }
        }
        writeln!(out, "}} as const;")?;
        Ok(())
    }

    // --- Function request/response/METHOD helpers ---

    #[allow(clippy::too_many_lines)]
    fn emit_functions(&mut self, out: &mut String) -> Result<()> {
        let iface_name = &self.interface.name;
        writeln!(
            out,
            "/** Checked protobuf request, response, and method helpers for `{iface_name}`. */"
        )?;
        writeln!(out, "export const functions = {{")?;

        let mut fn_names = BTreeMap::new();
        for (idx, function) in self.interface.functions.iter().enumerate() {
            if idx > 0 {
                writeln!(out)?;
            }
            let fn_ident = ts_value_ident(&function.name, "function")?;
            insert_name(
                &mut fn_names,
                &fn_ident,
                &function.name,
                &format!("interface `{iface_name}`"),
            )?;

            let req_proto =
                ident::proto_function_message_name(iface_name, &function.name, "Request");
            let resp_proto =
                ident::proto_function_message_name(iface_name, &function.name, "Response");
            let req_ty = self.local_proto_type_ref(&req_proto);
            let req_schema = self.local_proto_schema_ref(&req_proto);
            let resp_ty = self.local_proto_type_ref(&resp_proto);
            let resp_schema = self.local_proto_schema_ref(&resp_proto);

            let method_enum = ident::proto_method_enum_name(iface_name);
            let method_val = ident::proto_method_enum_value(iface_name, &function.name);
            let method_ref = self.local_proto_enum_value_ref(&method_enum, &method_val);
            self.imports.use_create();

            let mut param_idents = Vec::with_capacity(function.params.len());
            let mut param_types = Vec::with_capacity(function.params.len());
            let mut param_names_seen = BTreeMap::new();
            let fn_scope = format!("{iface_name}#{}", function.name);
            for param in &function.params {
                let p_ident = ts_value_ident(&param.name, "parameter")?;
                insert_name(&mut param_names_seen, &p_ident, &param.name, &fn_scope)?;
                let p_ty = self.plain_type(&param.ty)?;
                param_idents.push(p_ident);
                param_types.push(p_ty);
            }
            let arg_list: Vec<String> = param_idents
                .iter()
                .zip(&param_types)
                .map(|(n, ty)| format!("{n}: {ty}"))
                .collect();
            let from_req_ret = match param_types.len() {
                0 => "void".to_string(),
                1 => param_types[0].clone(),
                _ => format!("readonly [{}]", param_types.join(", ")),
            };
            let result_plain_ty = function
                .result
                .as_ref()
                .map(|ty| self.plain_type(ty))
                .transpose()?;

            let fallback = format!("Checked protobuf helpers for `{fn_scope}`.");
            write_jsdoc(out, 2, &function.docs, &function.stability, Some(&fallback))?;
            writeln!(out, "  {fn_ident}: {{")?;
            writeln!(out, "    METHOD: {method_ref},")?;
            writeln!(out, "    requestSchema: {req_schema},")?;
            writeln!(out, "    responseSchema: {resp_schema},")?;

            // toRequest
            writeln!(out, "    toRequest({}): {req_ty} {{", arg_list.join(", "))?;
            if function.params.is_empty() {
                writeln!(out, "      return _wf_create({req_schema});")?;
            } else {
                let mut stmts = Vec::new();
                let mut temps = TempGen::new();
                let mut req_pairs = Vec::new();
                let mut opt_pairs = Vec::new();
                for (param, p_ident) in function.params.iter().zip(&param_idents) {
                    let es_param = es_field_local_name(&param.name);
                    let identity = format!("{iface_name}#{}.{}", function.name, param.name);
                    let encoded = self.emit_encode_value(
                        &mut stmts, 6, &mut temps, p_ident, &param.ty, &identity,
                    )?;
                    if self.form(&param.ty)? == Form::Option {
                        let opt_var = if encoded.starts_with("_v") {
                            encoded
                        } else {
                            let var = temps.fresh();
                            stmts.push(format!("      const {var} = {encoded};"));
                            var
                        };
                        opt_pairs.push((es_param, opt_var));
                    } else {
                        req_pairs.push((es_param, encoded));
                    }
                }
                for stmt in stmts {
                    writeln!(out, "{stmt}")?;
                }
                if opt_pairs.is_empty() {
                    writeln!(out, "      return _wf_create({req_schema}, {{")?;
                    for (es_param, expr) in req_pairs {
                        writeln!(out, "        {es_param}: {expr},")?;
                    }
                    writeln!(out, "      }});")?;
                } else {
                    writeln!(out, "      const _out = _wf_create({req_schema}, {{")?;
                    for (es_param, expr) in req_pairs {
                        writeln!(out, "        {es_param}: {expr},")?;
                    }
                    writeln!(out, "      }});")?;
                    for (es_param, expr) in opt_pairs {
                        writeln!(out, "      if ({expr} !== undefined) {{")?;
                        writeln!(out, "        _out.{es_param} = {expr};")?;
                        writeln!(out, "      }}")?;
                    }
                    writeln!(out, "      return _out;")?;
                }
            }
            writeln!(out, "    }},")?;

            // fromRequest
            if function.params.is_empty() {
                writeln!(out, "    fromRequest(_value: {req_ty}): void {{")?;
                writeln!(out, "      return;")?;
                writeln!(out, "    }},")?;
            } else {
                writeln!(out, "    fromRequest(value: {req_ty}): {from_req_ret} {{")?;
                let mut stmts = Vec::new();
                let mut temps = TempGen::new();
                let mut decoded_vals = Vec::with_capacity(function.params.len());
                for param in &function.params {
                    let es_param = es_field_local_name(&param.name);
                    let identity = format!("{iface_name}#{}.{}", function.name, param.name);
                    let val = self.emit_decode_field(
                        &mut stmts,
                        6,
                        &mut temps,
                        &format!("value.{es_param}"),
                        &param.ty,
                        &identity,
                    )?;
                    decoded_vals.push(val);
                }
                for stmt in stmts {
                    writeln!(out, "{stmt}")?;
                }
                if decoded_vals.len() == 1 {
                    writeln!(out, "      return {};", decoded_vals[0])?;
                } else {
                    writeln!(out, "      return [{}];", decoded_vals.join(", "))?;
                }
                writeln!(out, "    }},")?;
            }

            // toResponse / fromResponse
            if let (Some(result_ty), Some(plain_ret)) = (&function.result, &result_plain_ty) {
                let identity = format!("{iface_name}#{}.result", function.name);
                writeln!(out, "    toResponse(value: {plain_ret}): {resp_ty} {{")?;
                let mut stmts = Vec::new();
                let mut temps = TempGen::new();
                let encoded = self
                    .emit_encode_value(&mut stmts, 6, &mut temps, "value", result_ty, &identity)?;
                for stmt in stmts {
                    writeln!(out, "{stmt}")?;
                }
                if self.form(result_ty)? == Form::Option {
                    let opt_var = if encoded.starts_with("_v") {
                        encoded
                    } else {
                        let var = temps.fresh();
                        writeln!(out, "      const {var} = {encoded};")?;
                        var
                    };
                    writeln!(out, "      const _out = _wf_create({resp_schema});")?;
                    writeln!(out, "      if ({opt_var} !== undefined) {{")?;
                    writeln!(out, "        _out.result = {opt_var};")?;
                    writeln!(out, "      }}")?;
                    writeln!(out, "      return _out;")?;
                } else {
                    writeln!(
                        out,
                        "      return _wf_create({resp_schema}, {{ result: {encoded} }});"
                    )?;
                }
                writeln!(out, "    }},")?;

                writeln!(out, "    fromResponse(value: {resp_ty}): {plain_ret} {{")?;
                let mut dec_stmts = Vec::new();
                let mut dec_temps = TempGen::new();
                let decoded = self.emit_decode_field(
                    &mut dec_stmts,
                    6,
                    &mut dec_temps,
                    "value.result",
                    result_ty,
                    &identity,
                )?;
                for stmt in dec_stmts {
                    writeln!(out, "{stmt}")?;
                }
                writeln!(out, "      return {decoded};")?;
                writeln!(out, "    }},")?;
            } else {
                writeln!(out, "    toResponse(): {resp_ty} {{")?;
                writeln!(out, "      return _wf_create({resp_schema});")?;
                writeln!(out, "    }},")?;
                writeln!(out, "    fromResponse(_value: {resp_ty}): void {{")?;
                writeln!(out, "      return;")?;
                writeln!(out, "    }},")?;
            }
            writeln!(out, "  }},")?;
        }
        writeln!(out, "}} as const;")?;
        Ok(())
    }

    // --- Primitive & container encode helpers ---

    fn emit_encode_primitive(
        &mut self,
        expr: &str,
        ty: &TypeExpr,
        identity: &str,
    ) -> Result<String> {
        let id = escape_ts_string(identity);
        match ty {
            TypeExpr::Bool | TypeExpr::F32 | TypeExpr::F64 | TypeExpr::String => {
                Ok(expr.to_string())
            }
            TypeExpr::U8 => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.checkU8({expr}, {id})"))
            }
            TypeExpr::U16 => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.checkU16({expr}, {id})"))
            }
            TypeExpr::U32 => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.checkU32({expr}, {id})"))
            }
            TypeExpr::U64 => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.checkU64({expr}, {id})"))
            }
            TypeExpr::S8 => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.checkS8({expr}, {id})"))
            }
            TypeExpr::S16 => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.checkS16({expr}, {id})"))
            }
            TypeExpr::S32 => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.checkS32({expr}, {id})"))
            }
            TypeExpr::S64 => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.checkS64({expr}, {id})"))
            }
            TypeExpr::Char => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.encodeChar({expr}, {id})"))
            }
            _ => bail!("type `{ty:?}` is not a primitive"),
        }
    }

    fn emit_encode_value(
        &mut self,
        stmts: &mut Vec<String>,
        indent: usize,
        temps: &mut TempGen,
        expr: &str,
        ty: &TypeExpr,
        identity: &str,
    ) -> Result<String> {
        match ty {
            TypeExpr::Bool
            | TypeExpr::U8
            | TypeExpr::U16
            | TypeExpr::U32
            | TypeExpr::U64
            | TypeExpr::S8
            | TypeExpr::S16
            | TypeExpr::S32
            | TypeExpr::S64
            | TypeExpr::F32
            | TypeExpr::F64
            | TypeExpr::Char
            | TypeExpr::String => self.emit_encode_primitive(expr, ty, identity),
            TypeExpr::List(element) if self.ctx.model.resolves_to_u8(element) => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.cloneBytes({expr})"))
            }
            TypeExpr::List(element) => {
                self.emit_encode_list(stmts, indent, temps, expr, element, None, identity)
            }
            TypeExpr::FixedLengthList(element, len) if self.ctx.model.resolves_to_u8(element) => {
                self.imports.use_helpers();
                let pad = " ".repeat(indent);
                let id = escape_ts_string(identity);
                stmts.push(format!(
                    "{pad}_wf_h.checkLength({expr}.length, {len}, {id});"
                ));
                Ok(format!("_wf_h.cloneBytes({expr})"))
            }
            TypeExpr::FixedLengthList(element, len) => {
                self.emit_encode_list(stmts, indent, temps, expr, element, Some(*len), identity)
            }
            TypeExpr::Map(key, value) => {
                self.emit_encode_map(stmts, indent, temps, expr, key, value, identity)
            }
            TypeExpr::Option(payload) => {
                self.emit_encode_option_direct(stmts, indent, temps, expr, payload, identity)
            }
            TypeExpr::Result(result) => {
                self.emit_encode_inline_result(stmts, indent, temps, expr, result, identity)
            }
            TypeExpr::Named(name) => {
                if name.is_foreign() {
                    let target = self.glue_target_expr(name)?;
                    return Ok(format!("{target}.toProto({expr})"));
                }
                let def = self.named(name)?;
                if let TypeDefKind::Alias(target) = &def.kind {
                    self.emit_encode_value(stmts, indent, temps, expr, target, identity)
                } else {
                    let target = self.glue_target_expr(name)?;
                    Ok(format!("{target}.toProto({expr})"))
                }
            }
        }
    }

    #[allow(clippy::too_many_lines)]
    fn emit_encode_singular(
        &mut self,
        stmts: &mut Vec<String>,
        indent: usize,
        temps: &mut TempGen,
        expr: &str,
        ty: &TypeExpr,
        identity: &str,
    ) -> Result<String> {
        match ty {
            TypeExpr::Bool
            | TypeExpr::U8
            | TypeExpr::U16
            | TypeExpr::U32
            | TypeExpr::U64
            | TypeExpr::S8
            | TypeExpr::S16
            | TypeExpr::S32
            | TypeExpr::S64
            | TypeExpr::F32
            | TypeExpr::F64
            | TypeExpr::Char
            | TypeExpr::String => self.emit_encode_primitive(expr, ty, identity),
            TypeExpr::List(element) if self.ctx.model.resolves_to_u8(element) => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.cloneBytes({expr})"))
            }
            TypeExpr::FixedLengthList(element, len) if self.ctx.model.resolves_to_u8(element) => {
                self.imports.use_helpers();
                let pad = " ".repeat(indent);
                let id = escape_ts_string(identity);
                stmts.push(format!(
                    "{pad}_wf_h.checkLength({expr}.length, {len}, {id});"
                ));
                Ok(format!("_wf_h.cloneBytes({expr})"))
            }
            TypeExpr::List(element) => {
                let wrapper_proto = format!("WitforgeListOf{}", self.shape_name(element)?);
                let wrapper_schema = self.local_proto_schema_ref(&wrapper_proto);
                self.imports.use_create();
                let values =
                    self.emit_encode_list(stmts, indent, temps, expr, element, None, identity)?;
                Ok(format!(
                    "_wf_create({wrapper_schema}, {{ values: {values} }})"
                ))
            }
            TypeExpr::FixedLengthList(element, len) => {
                let wrapper_proto = format!("WitforgeListOf{}", self.shape_name(element)?);
                let wrapper_schema = self.local_proto_schema_ref(&wrapper_proto);
                self.imports.use_create();
                let values = self.emit_encode_list(
                    stmts,
                    indent,
                    temps,
                    expr,
                    element,
                    Some(*len),
                    identity,
                )?;
                Ok(format!(
                    "_wf_create({wrapper_schema}, {{ values: {values} }})"
                ))
            }
            TypeExpr::Map(key, value) => {
                let wrapper_proto = format!(
                    "WitforgeMapOf{}And{}",
                    self.shape_name(key)?,
                    self.shape_name(value)?
                );
                let wrapper_schema = self.local_proto_schema_ref(&wrapper_proto);
                self.imports.use_create();
                let entries =
                    self.emit_encode_map(stmts, indent, temps, expr, key, value, identity)?;
                Ok(format!(
                    "_wf_create({wrapper_schema}, {{ entries: {entries} }})"
                ))
            }
            TypeExpr::Option(payload) => {
                let wrapper_proto = format!("WitforgeOptionOf{}", self.shape_name(payload)?);
                self.emit_encode_option_wrapper(
                    stmts,
                    indent,
                    temps,
                    expr,
                    &wrapper_proto,
                    payload,
                    identity,
                )
            }
            TypeExpr::Result(result) => {
                self.emit_encode_inline_result(stmts, indent, temps, expr, result, identity)
            }
            TypeExpr::Named(name) => {
                if name.is_foreign() {
                    let (dep, def) = self
                        .foreign_type_def(None, name)?
                        .context("foreign type needs a dependency package")?;
                    match &def.kind {
                        TypeDefKind::Alias(target) => {
                            let qualified = qualify_type(Some(dep), target);
                            return self.emit_encode_singular(
                                stmts, indent, temps, expr, &qualified, identity,
                            );
                        }
                        TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _)
                            if self.ctx.model.resolves_to_u8_in(Some(dep), element) =>
                        {
                            let target = self.glue_target_expr(name)?;
                            return Ok(format!("{target}.toProto({expr})"));
                        }
                        TypeDefKind::List(_) | TypeDefKind::FixedLengthList(_, _) => {
                            let shape =
                                self.foreign_shape_name_for_caller(None, dep, name, &def.kind)?;
                            let wrapper_schema =
                                self.local_proto_schema_ref(&format!("Witforge{shape}"));
                            self.imports.use_create();
                            let target = self.glue_target_expr(name)?;
                            return Ok(format!(
                                "_wf_create({wrapper_schema}, {{ values: {target}.toProto({expr}) }})"
                            ));
                        }
                        TypeDefKind::Map(_, _) => {
                            let shape =
                                self.foreign_shape_name_for_caller(None, dep, name, &def.kind)?;
                            let wrapper_schema =
                                self.local_proto_schema_ref(&format!("Witforge{shape}"));
                            self.imports.use_create();
                            let target = self.glue_target_expr(name)?;
                            return Ok(format!(
                                "_wf_create({wrapper_schema}, {{ entries: {target}.toProto({expr}) }})"
                            ));
                        }
                        TypeDefKind::Option(_) => {
                            let shape =
                                self.foreign_shape_name_for_caller(None, dep, name, &def.kind)?;
                            let wrapper_proto = format!("Witforge{shape}");
                            let target = self.glue_target_expr(name)?;
                            return Ok(self.emit_wrap_option_call(
                                stmts,
                                indent,
                                temps,
                                &format!("{target}.toProto({expr})"),
                                &wrapper_proto,
                            ));
                        }
                        _ => {
                            let target = self.glue_target_expr(name)?;
                            return Ok(format!("{target}.toProto({expr})"));
                        }
                    }
                }

                let def = self.named(name)?;
                match &def.kind {
                    TypeDefKind::Alias(target) => {
                        self.emit_encode_singular(stmts, indent, temps, expr, target, identity)
                    }
                    TypeDefKind::Record(_)
                    | TypeDefKind::Variant(_)
                    | TypeDefKind::Flags(_)
                    | TypeDefKind::Result(_)
                    | TypeDefKind::Enum(_) => {
                        let target = self.glue_target_expr(name)?;
                        Ok(format!("{target}.toProto({expr})"))
                    }
                    TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _)
                        if self.ctx.model.resolves_to_u8(element) =>
                    {
                        let target = self.glue_target_expr(name)?;
                        Ok(format!("{target}.toProto({expr})"))
                    }
                    TypeDefKind::List(_) | TypeDefKind::FixedLengthList(_, _) => {
                        let shape = self.shape_name(ty)?;
                        let wrapper_schema =
                            self.local_proto_schema_ref(&format!("Witforge{shape}"));
                        self.imports.use_create();
                        let target = self.glue_target_expr(name)?;
                        Ok(format!(
                            "_wf_create({wrapper_schema}, {{ values: {target}.toProto({expr}) }})"
                        ))
                    }
                    TypeDefKind::Map(_, _) => {
                        let shape = self.shape_name(ty)?;
                        let wrapper_schema =
                            self.local_proto_schema_ref(&format!("Witforge{shape}"));
                        self.imports.use_create();
                        let target = self.glue_target_expr(name)?;
                        Ok(format!(
                            "_wf_create({wrapper_schema}, {{ entries: {target}.toProto({expr}) }})"
                        ))
                    }
                    TypeDefKind::Option(payload) => {
                        let wrapper_proto =
                            if matches!(self.form(payload)?, Form::List | Form::Map | Form::Option)
                            {
                                format!(
                                    "WitforgeOptionOf{}",
                                    ident::proto_type_name(&name.interface, &name.name)
                                )
                            } else {
                                format!("WitforgeOptionOf{}", self.shape_name(payload)?)
                            };
                        let target = self.glue_target_expr(name)?;
                        Ok(self.emit_wrap_option_call(
                            stmts,
                            indent,
                            temps,
                            &format!("{target}.toProto({expr})"),
                            &wrapper_proto,
                        ))
                    }
                }
            }
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn emit_encode_list(
        &mut self,
        stmts: &mut Vec<String>,
        indent: usize,
        temps: &mut TempGen,
        expr: &str,
        element: &TypeExpr,
        fixed_len: Option<u32>,
        identity: &str,
    ) -> Result<String> {
        let pad = " ".repeat(indent);
        let inner_pad = " ".repeat(indent + 2);
        if let Some(len) = fixed_len {
            self.imports.use_helpers();
            let id = escape_ts_string(identity);
            stmts.push(format!(
                "{pad}_wf_h.checkLength({expr}.length, {len}, {id});"
            ));
        }
        let elem_proto_ty = self.proto_singular_type(element)?;
        let out_var = temps.fresh();
        let item_var = temps.fresh();
        let mut loop_stmts = Vec::new();
        let encoded = self.emit_encode_singular(
            &mut loop_stmts,
            indent + 2,
            temps,
            &item_var,
            element,
            identity,
        )?;
        let mut block = format!("{pad}const {out_var}: {elem_proto_ty}[] = [];\n");
        let _ = writeln!(block, "{pad}for (const {item_var} of {expr}) {{");
        for stmt in loop_stmts {
            let _ = writeln!(block, "{stmt}");
        }
        let _ = writeln!(block, "{inner_pad}{out_var}.push({encoded});");
        let _ = write!(block, "{pad}}}");
        stmts.push(block);
        Ok(out_var)
    }

    #[allow(clippy::too_many_arguments)]
    fn emit_encode_map(
        &mut self,
        stmts: &mut Vec<String>,
        indent: usize,
        temps: &mut TempGen,
        expr: &str,
        key: &TypeExpr,
        value: &TypeExpr,
        identity: &str,
    ) -> Result<String> {
        self.imports.use_helpers();
        let pad = " ".repeat(indent);
        let inner_pad = " ".repeat(indent + 2);
        let key_ts_ty = Self::proto_map_key_ts_type(key)?;
        let val_proto_ty = self.proto_singular_type(value)?;
        let out_var = temps.fresh();
        let key_var = temps.fresh();
        let val_var = temps.fresh();

        let mut loop_stmts = Vec::new();
        let checked_key = self.emit_encode_primitive(&key_var, key, identity)?;
        let raw_key_expr = match key {
            TypeExpr::Bool => format!("{checked_key} ? \"true\" : \"false\""),
            TypeExpr::U64 | TypeExpr::S64 => format!("{checked_key}.toString()"),
            _ => checked_key,
        };
        let encoded_val = self.emit_encode_singular(
            &mut loop_stmts,
            indent + 2,
            temps,
            &val_var,
            value,
            identity,
        )?;
        let mut block =
            format!("{pad}const {out_var}: {{ [key: {key_ts_ty}]: {val_proto_ty} }} = {{}};\n");
        let _ = writeln!(
            block,
            "{pad}for (const [{key_var}, {val_var}] of {expr}.entries()) {{"
        );
        for stmt in loop_stmts {
            let _ = writeln!(block, "{stmt}");
        }
        let _ = writeln!(
            block,
            "{inner_pad}_wf_h.setMapEntry({out_var}, {raw_key_expr}, {encoded_val});"
        );
        let _ = write!(block, "{pad}}}");
        stmts.push(block);
        Ok(out_var)
    }

    fn emit_encode_option_direct(
        &mut self,
        stmts: &mut Vec<String>,
        indent: usize,
        temps: &mut TempGen,
        expr: &str,
        payload: &TypeExpr,
        identity: &str,
    ) -> Result<String> {
        self.imports.use_error();
        let pad = " ".repeat(indent);
        let inner_pad = " ".repeat(indent + 2);
        let id = escape_ts_string(identity);
        let proto_inner = self.proto_singular_type(payload)?;
        let out_var = temps.fresh();
        let input_var = temps.fresh();
        let mut some_stmts = Vec::new();
        let encoded = self.emit_encode_singular(
            &mut some_stmts,
            indent + 2,
            temps,
            &format!("{input_var}.value"),
            payload,
            identity,
        )?;
        let mut block = format!("{pad}let {out_var}: {proto_inner} | undefined = undefined;\n");
        let _ = writeln!(block, "{pad}const {input_var} = {expr};");
        let _ = writeln!(block, "{pad}if ({input_var}.tag === \"some\") {{");
        for stmt in some_stmts {
            let _ = writeln!(block, "{stmt}");
        }
        let _ = writeln!(block, "{inner_pad}{out_var} = {encoded};");
        let _ = writeln!(block, "{pad}}} else if ({input_var}.tag !== \"none\") {{");
        let _ = writeln!(
            block,
            "{inner_pad}throw new _wf_Error(\"InvalidState\", {{ message: {id} }});"
        );
        let _ = write!(block, "{pad}}}");
        stmts.push(block);
        Ok(out_var)
    }

    #[allow(clippy::too_many_arguments)]
    fn emit_encode_option_wrapper(
        &mut self,
        stmts: &mut Vec<String>,
        indent: usize,
        temps: &mut TempGen,
        expr: &str,
        wrapper_proto: &str,
        payload: &TypeExpr,
        identity: &str,
    ) -> Result<String> {
        let wrapper_ty = self.local_proto_type_ref(wrapper_proto);
        let wrapper_schema = self.local_proto_schema_ref(wrapper_proto);
        let empty_schema = self.local_proto_schema_ref("Empty");
        self.imports.use_create();
        self.imports.use_error();
        let pad = " ".repeat(indent);
        let inner_pad = " ".repeat(indent + 2);
        let id = escape_ts_string(identity);
        let out_var = temps.fresh();
        let input_var = temps.fresh();
        let mut some_stmts = Vec::new();
        let encoded = self.emit_encode_singular(
            &mut some_stmts,
            indent + 2,
            temps,
            &format!("{input_var}.value"),
            payload,
            identity,
        )?;
        let mut block = format!("{pad}let {out_var}: {wrapper_ty};\n");
        let _ = writeln!(block, "{pad}const {input_var} = {expr};");
        let _ = writeln!(block, "{pad}if ({input_var}.tag === \"none\") {{");
        let _ = writeln!(
            block,
            "{inner_pad}{out_var} = _wf_create({wrapper_schema}, {{ value: {{ case: \"none\", value: _wf_create({empty_schema}) }} }});"
        );
        let _ = writeln!(block, "{pad}}} else if ({input_var}.tag === \"some\") {{");
        for stmt in some_stmts {
            let _ = writeln!(block, "{stmt}");
        }
        let _ = writeln!(
            block,
            "{inner_pad}{out_var} = _wf_create({wrapper_schema}, {{ value: {{ case: \"some\", value: {encoded} }} }});"
        );
        let _ = writeln!(block, "{pad}}} else {{");
        let _ = writeln!(
            block,
            "{inner_pad}throw new _wf_Error(\"InvalidState\", {{ message: {id} }});"
        );
        let _ = write!(block, "{pad}}}");
        stmts.push(block);
        Ok(out_var)
    }

    fn emit_wrap_option_call(
        &mut self,
        stmts: &mut Vec<String>,
        indent: usize,
        temps: &mut TempGen,
        converted_expr: &str,
        wrapper_proto: &str,
    ) -> String {
        let wrapper_schema = self.local_proto_schema_ref(wrapper_proto);
        let empty_schema = self.local_proto_schema_ref("Empty");
        self.imports.use_create();
        let pad = " ".repeat(indent);
        let tmp = temps.fresh();
        stmts.push(format!("{pad}const {tmp} = {converted_expr};"));
        format!(
            "_wf_create({wrapper_schema}, {{ value: {tmp} === undefined ? {{ case: \"none\", value: _wf_create({empty_schema}) }} : {{ case: \"some\", value: {tmp} }} }})"
        )
    }

    fn emit_encode_inline_result(
        &mut self,
        stmts: &mut Vec<String>,
        indent: usize,
        temps: &mut TempGen,
        expr: &str,
        result: &ResultExpr,
        identity: &str,
    ) -> Result<String> {
        let shape = self.shape_name(&TypeExpr::Result(result.clone()))?;
        let wrapper_proto = format!("Witforge{shape}");
        let wrapper_ty = self.local_proto_type_ref(&wrapper_proto);
        let wrapper_schema = self.local_proto_schema_ref(&wrapper_proto);
        self.imports.use_create();
        self.imports.use_error();

        let pad = " ".repeat(indent);
        let inner_pad = " ".repeat(indent + 2);
        let id = escape_ts_string(identity);
        let out_var = temps.fresh();
        let res_var = temps.fresh();
        let mut block = format!("{pad}let {out_var}: {wrapper_ty};\n");
        let _ = writeln!(block, "{pad}const {res_var} = {expr};");
        let _ = writeln!(block, "{pad}if ({res_var}.tag === \"ok\") {{");
        if let Some(ok_ty) = &result.ok {
            let mut ok_stmts = Vec::new();
            let encoded = self.emit_encode_singular(
                &mut ok_stmts,
                indent + 2,
                temps,
                &format!("{res_var}.value"),
                ok_ty,
                identity,
            )?;
            for stmt in ok_stmts {
                let _ = writeln!(block, "{stmt}");
            }
            let _ = writeln!(
                block,
                "{inner_pad}{out_var} = _wf_create({wrapper_schema}, {{ value: {{ case: \"ok\", value: {encoded} }} }});"
            );
        } else {
            let empty_schema = self.local_proto_schema_ref("Empty");
            let _ = writeln!(
                block,
                "{inner_pad}{out_var} = _wf_create({wrapper_schema}, {{ value: {{ case: \"ok\", value: _wf_create({empty_schema}) }} }});"
            );
        }
        let _ = writeln!(block, "{pad}}} else if ({res_var}.tag === \"err\") {{");
        if let Some(err_ty) = &result.err {
            let mut err_stmts = Vec::new();
            let encoded = self.emit_encode_singular(
                &mut err_stmts,
                indent + 2,
                temps,
                &format!("{res_var}.error"),
                err_ty,
                identity,
            )?;
            for stmt in err_stmts {
                let _ = writeln!(block, "{stmt}");
            }
            let _ = writeln!(
                block,
                "{inner_pad}{out_var} = _wf_create({wrapper_schema}, {{ value: {{ case: \"err\", value: {encoded} }} }});"
            );
        } else {
            let empty_schema = self.local_proto_schema_ref("Empty");
            let _ = writeln!(
                block,
                "{inner_pad}{out_var} = _wf_create({wrapper_schema}, {{ value: {{ case: \"err\", value: _wf_create({empty_schema}) }} }});"
            );
        }
        let _ = writeln!(block, "{pad}}} else {{");
        let _ = writeln!(
            block,
            "{inner_pad}throw new _wf_Error(\"UnknownCase\", {{ message: {id} }});"
        );
        let _ = write!(block, "{pad}}}");
        stmts.push(block);
        Ok(out_var)
    }

    // --- Primitive & container decode helpers ---

    fn emit_decode_primitive(
        &mut self,
        expr: &str,
        ty: &TypeExpr,
        identity: &str,
    ) -> Result<String> {
        let id = escape_ts_string(identity);
        match ty {
            TypeExpr::Bool | TypeExpr::F32 | TypeExpr::F64 | TypeExpr::String => {
                Ok(expr.to_string())
            }
            TypeExpr::U8 => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.checkU8({expr}, {id})"))
            }
            TypeExpr::U16 => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.checkU16({expr}, {id})"))
            }
            TypeExpr::U32 => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.checkU32({expr}, {id})"))
            }
            TypeExpr::U64 => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.checkU64({expr}, {id})"))
            }
            TypeExpr::S8 => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.checkS8({expr}, {id})"))
            }
            TypeExpr::S16 => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.checkS16({expr}, {id})"))
            }
            TypeExpr::S32 => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.checkS32({expr}, {id})"))
            }
            TypeExpr::S64 => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.checkS64({expr}, {id})"))
            }
            TypeExpr::Char => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.decodeChar({expr}, {id})"))
            }
            _ => bail!("type `{ty:?}` is not a primitive"),
        }
    }

    fn emit_decode_field(
        &mut self,
        stmts: &mut Vec<String>,
        indent: usize,
        temps: &mut TempGen,
        expr: &str,
        ty: &TypeExpr,
        identity: &str,
    ) -> Result<String> {
        match self.form(ty)? {
            Form::List | Form::Map | Form::Option => {
                self.emit_decode_value(stmts, indent, temps, expr, ty, identity)
            }
            Form::Scalar | Form::Bytes | Form::Enum | Form::Message => {
                self.imports.use_helpers();
                let pad = " ".repeat(indent);
                let id = escape_ts_string(identity);
                let val_var = temps.fresh();
                stmts.push(format!(
                    "{pad}const {val_var} = _wf_h.requirePresent({expr}, {id});"
                ));
                self.emit_decode_value(stmts, indent, temps, &val_var, ty, identity)
            }
        }
    }

    fn emit_decode_value(
        &mut self,
        stmts: &mut Vec<String>,
        indent: usize,
        temps: &mut TempGen,
        expr: &str,
        ty: &TypeExpr,
        identity: &str,
    ) -> Result<String> {
        match ty {
            TypeExpr::Bool
            | TypeExpr::U8
            | TypeExpr::U16
            | TypeExpr::U32
            | TypeExpr::U64
            | TypeExpr::S8
            | TypeExpr::S16
            | TypeExpr::S32
            | TypeExpr::S64
            | TypeExpr::F32
            | TypeExpr::F64
            | TypeExpr::Char
            | TypeExpr::String => self.emit_decode_primitive(expr, ty, identity),
            TypeExpr::List(element) if self.ctx.model.resolves_to_u8(element) => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.cloneBytes({expr})"))
            }
            TypeExpr::List(element) => {
                self.emit_decode_list(stmts, indent, temps, expr, element, None, identity)
            }
            TypeExpr::FixedLengthList(element, len) if self.ctx.model.resolves_to_u8(element) => {
                self.imports.use_helpers();
                let pad = " ".repeat(indent);
                let id = escape_ts_string(identity);
                stmts.push(format!(
                    "{pad}_wf_h.checkLength({expr}.length, {len}, {id});"
                ));
                Ok(format!("_wf_h.cloneBytes({expr})"))
            }
            TypeExpr::FixedLengthList(element, len) => {
                self.emit_decode_list(stmts, indent, temps, expr, element, Some(*len), identity)
            }
            TypeExpr::Map(key, value) => {
                self.emit_decode_map(stmts, indent, temps, expr, key, value, identity)
            }
            TypeExpr::Option(payload) => {
                self.emit_decode_option_direct(stmts, indent, temps, expr, payload, identity)
            }
            TypeExpr::Result(result) => {
                self.emit_decode_inline_result(stmts, indent, temps, expr, result, identity)
            }
            TypeExpr::Named(name) => {
                if name.is_foreign() {
                    let target = self.glue_target_expr(name)?;
                    return Ok(format!("{target}.fromProto({expr})"));
                }
                let def = self.named(name)?;
                if let TypeDefKind::Alias(target) = &def.kind {
                    self.emit_decode_value(stmts, indent, temps, expr, target, identity)
                } else {
                    let target = self.glue_target_expr(name)?;
                    Ok(format!("{target}.fromProto({expr})"))
                }
            }
        }
    }

    #[allow(clippy::too_many_lines)]
    fn emit_decode_singular(
        &mut self,
        stmts: &mut Vec<String>,
        indent: usize,
        temps: &mut TempGen,
        expr: &str,
        ty: &TypeExpr,
        identity: &str,
    ) -> Result<String> {
        match ty {
            TypeExpr::Bool
            | TypeExpr::U8
            | TypeExpr::U16
            | TypeExpr::U32
            | TypeExpr::U64
            | TypeExpr::S8
            | TypeExpr::S16
            | TypeExpr::S32
            | TypeExpr::S64
            | TypeExpr::F32
            | TypeExpr::F64
            | TypeExpr::Char
            | TypeExpr::String => self.emit_decode_primitive(expr, ty, identity),
            TypeExpr::List(element) if self.ctx.model.resolves_to_u8(element) => {
                self.imports.use_helpers();
                Ok(format!("_wf_h.cloneBytes({expr})"))
            }
            TypeExpr::FixedLengthList(element, len) if self.ctx.model.resolves_to_u8(element) => {
                self.imports.use_helpers();
                let pad = " ".repeat(indent);
                let id = escape_ts_string(identity);
                stmts.push(format!(
                    "{pad}_wf_h.checkLength({expr}.length, {len}, {id});"
                ));
                Ok(format!("_wf_h.cloneBytes({expr})"))
            }
            TypeExpr::List(element) => self.emit_decode_list(
                stmts,
                indent,
                temps,
                &format!("{expr}.values"),
                element,
                None,
                identity,
            ),
            TypeExpr::FixedLengthList(element, len) => self.emit_decode_list(
                stmts,
                indent,
                temps,
                &format!("{expr}.values"),
                element,
                Some(*len),
                identity,
            ),
            TypeExpr::Map(key, value) => self.emit_decode_map(
                stmts,
                indent,
                temps,
                &format!("{expr}.entries"),
                key,
                value,
                identity,
            ),
            TypeExpr::Option(payload) => {
                self.emit_decode_option_wrapper(stmts, indent, temps, expr, payload, identity)
            }
            TypeExpr::Result(result) => {
                self.emit_decode_inline_result(stmts, indent, temps, expr, result, identity)
            }
            TypeExpr::Named(name) => {
                if name.is_foreign() {
                    let (dep, def) = self
                        .foreign_type_def(None, name)?
                        .context("foreign type needs a dependency package")?;
                    match &def.kind {
                        TypeDefKind::Alias(target) => {
                            let qualified = qualify_type(Some(dep), target);
                            return self.emit_decode_singular(
                                stmts, indent, temps, expr, &qualified, identity,
                            );
                        }
                        TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _)
                            if self.ctx.model.resolves_to_u8_in(Some(dep), element) =>
                        {
                            let target = self.glue_target_expr(name)?;
                            return Ok(format!("{target}.fromProto({expr})"));
                        }
                        TypeDefKind::List(_) | TypeDefKind::FixedLengthList(_, _) => {
                            let target = self.glue_target_expr(name)?;
                            return Ok(format!("{target}.fromProto({expr}.values)"));
                        }
                        TypeDefKind::Map(_, _) => {
                            let target = self.glue_target_expr(name)?;
                            return Ok(format!("{target}.fromProto({expr}.entries)"));
                        }
                        TypeDefKind::Option(_) => {
                            let target = self.glue_target_expr(name)?;
                            let plain_ty = self.plain_named_type(name)?;
                            return Ok(self.emit_decode_named_option_wrapper(
                                stmts, indent, temps, expr, &target, &plain_ty, identity,
                            ));
                        }
                        _ => {
                            let target = self.glue_target_expr(name)?;
                            return Ok(format!("{target}.fromProto({expr})"));
                        }
                    }
                }
                let def = self.named(name)?;
                match &def.kind {
                    TypeDefKind::Alias(target) => {
                        self.emit_decode_singular(stmts, indent, temps, expr, target, identity)
                    }
                    TypeDefKind::Record(_)
                    | TypeDefKind::Variant(_)
                    | TypeDefKind::Flags(_)
                    | TypeDefKind::Result(_)
                    | TypeDefKind::Enum(_) => {
                        let target = self.glue_target_expr(name)?;
                        Ok(format!("{target}.fromProto({expr})"))
                    }
                    TypeDefKind::List(element) | TypeDefKind::FixedLengthList(element, _)
                        if self.ctx.model.resolves_to_u8(element) =>
                    {
                        let target = self.glue_target_expr(name)?;
                        Ok(format!("{target}.fromProto({expr})"))
                    }
                    TypeDefKind::List(_) | TypeDefKind::FixedLengthList(_, _) => {
                        let target = self.glue_target_expr(name)?;
                        Ok(format!("{target}.fromProto({expr}.values)"))
                    }
                    TypeDefKind::Map(_, _) => {
                        let target = self.glue_target_expr(name)?;
                        Ok(format!("{target}.fromProto({expr}.entries)"))
                    }
                    TypeDefKind::Option(_) => {
                        let target = self.glue_target_expr(name)?;
                        let plain_ty = self.plain_named_type(name)?;
                        Ok(self.emit_decode_named_option_wrapper(
                            stmts, indent, temps, expr, &target, &plain_ty, identity,
                        ))
                    }
                }
            }
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn emit_decode_list(
        &mut self,
        stmts: &mut Vec<String>,
        indent: usize,
        temps: &mut TempGen,
        expr: &str,
        element: &TypeExpr,
        fixed_len: Option<u32>,
        identity: &str,
    ) -> Result<String> {
        let pad = " ".repeat(indent);
        let inner_pad = " ".repeat(indent + 2);
        if let Some(len) = fixed_len {
            self.imports.use_helpers();
            let id = escape_ts_string(identity);
            stmts.push(format!(
                "{pad}_wf_h.checkLength({expr}.length, {len}, {id});"
            ));
        }
        let elem_plain_ty = self.plain_type(element)?;
        let elem_annot = if matches!(
            element,
            TypeExpr::Result(_) | TypeExpr::List(_) | TypeExpr::FixedLengthList(_, _)
        ) && elem_plain_ty != "Uint8Array"
        {
            format!("({elem_plain_ty})[]")
        } else {
            format!("{elem_plain_ty}[]")
        };
        let out_var = temps.fresh();
        let item_var = temps.fresh();
        let mut loop_stmts = Vec::new();
        let decoded = self.emit_decode_singular(
            &mut loop_stmts,
            indent + 2,
            temps,
            &item_var,
            element,
            identity,
        )?;
        let mut block = format!("{pad}const {out_var}: {elem_annot} = [];\n");
        let _ = writeln!(block, "{pad}for (const {item_var} of {expr}) {{");
        for stmt in loop_stmts {
            let _ = writeln!(block, "{stmt}");
        }
        let _ = writeln!(block, "{inner_pad}{out_var}.push({decoded});");
        let _ = write!(block, "{pad}}}");
        stmts.push(block);
        Ok(out_var)
    }

    #[allow(clippy::too_many_arguments)]
    fn emit_decode_map(
        &mut self,
        stmts: &mut Vec<String>,
        indent: usize,
        temps: &mut TempGen,
        expr: &str,
        key: &TypeExpr,
        value: &TypeExpr,
        identity: &str,
    ) -> Result<String> {
        self.imports.use_helpers();
        let pad = " ".repeat(indent);
        let inner_pad = " ".repeat(indent + 2);
        let id = escape_ts_string(identity);
        let k_plain_ty = self.plain_type(key)?;
        let v_plain_ty = self.plain_type(value)?;
        let out_var = temps.fresh();
        let raw_k = temps.fresh();
        let raw_v = temps.fresh();

        let mut loop_stmts = Vec::new();
        let dec_key = match key {
            TypeExpr::String => raw_k.clone(),
            TypeExpr::Bool => format!("_wf_h.parseMapBoolKey({raw_k}, {id})"),
            TypeExpr::Char => format!("_wf_h.parseMapCharKey({raw_k}, {id})"),
            TypeExpr::U64 | TypeExpr::S64 => {
                let parsed = format!("_wf_h.parseMapBigIntKey({raw_k}, {id})");
                self.emit_decode_primitive(&parsed, key, identity)?
            }
            TypeExpr::U8
            | TypeExpr::U16
            | TypeExpr::U32
            | TypeExpr::S8
            | TypeExpr::S16
            | TypeExpr::S32 => {
                let parsed = format!("_wf_h.parseMapIntKey({raw_k}, {id})");
                self.emit_decode_primitive(&parsed, key, identity)?
            }
            _ => bail!("map key `{key:?}` is not a valid primitive map key"),
        };
        let dec_val =
            self.emit_decode_singular(&mut loop_stmts, indent + 2, temps, &raw_v, value, identity)?;

        let mut block = format!("{pad}const {out_var} = new Map<{k_plain_ty}, {v_plain_ty}>();\n");
        let _ = writeln!(
            block,
            "{pad}for (const [{raw_k}, {raw_v}] of _wf_h.mapEntries({expr})) {{"
        );
        for stmt in loop_stmts {
            let _ = writeln!(block, "{stmt}");
        }
        let _ = writeln!(block, "{inner_pad}{out_var}.set({dec_key}, {dec_val});");
        let _ = write!(block, "{pad}}}");
        stmts.push(block);
        Ok(out_var)
    }

    fn emit_decode_option_direct(
        &mut self,
        stmts: &mut Vec<String>,
        indent: usize,
        temps: &mut TempGen,
        expr: &str,
        payload: &TypeExpr,
        identity: &str,
    ) -> Result<String> {
        self.imports.use_option_type();
        self.imports.use_none();
        self.imports.use_some();
        let pad = " ".repeat(indent);
        let inner_pad = " ".repeat(indent + 2);
        let inner_plain = self.plain_type(payload)?;
        let out_var = temps.fresh();
        let raw_var = temps.fresh();
        let mut some_stmts = Vec::new();
        let decoded = self.emit_decode_singular(
            &mut some_stmts,
            indent + 2,
            temps,
            &raw_var,
            payload,
            identity,
        )?;
        let mut block = format!("{pad}let {out_var}: _wf_Option<{inner_plain}> = _wf_NONE;\n");
        let _ = writeln!(block, "{pad}const {raw_var} = {expr};");
        let _ = writeln!(block, "{pad}if ({raw_var} !== undefined) {{");
        for stmt in some_stmts {
            let _ = writeln!(block, "{stmt}");
        }
        let _ = writeln!(block, "{inner_pad}{out_var} = _wf_some({decoded});");
        let _ = write!(block, "{pad}}}");
        stmts.push(block);
        Ok(out_var)
    }

    fn emit_decode_option_wrapper(
        &mut self,
        stmts: &mut Vec<String>,
        indent: usize,
        temps: &mut TempGen,
        expr: &str,
        payload: &TypeExpr,
        identity: &str,
    ) -> Result<String> {
        self.imports.use_error();
        self.imports.use_option_type();
        self.imports.use_none();
        self.imports.use_some();
        let pad = " ".repeat(indent);
        let inner_pad = " ".repeat(indent + 2);
        let id = escape_ts_string(identity);
        let inner_plain = self.plain_type(payload)?;
        let out_var = temps.fresh();
        let wrap_var = temps.fresh();
        let mut some_stmts = Vec::new();
        let decoded = self.emit_decode_singular(
            &mut some_stmts,
            indent + 2,
            temps,
            &format!("{wrap_var}.value.value"),
            payload,
            identity,
        )?;
        let mut block = format!("{pad}let {out_var}: _wf_Option<{inner_plain}>;\n");
        let _ = writeln!(block, "{pad}const {wrap_var} = {expr};");
        let _ = writeln!(block, "{pad}if ({wrap_var}.value.case === \"none\") {{");
        let _ = writeln!(block, "{inner_pad}{out_var} = _wf_NONE;");
        let _ = writeln!(
            block,
            "{pad}}} else if ({wrap_var}.value.case === \"some\") {{"
        );
        for stmt in some_stmts {
            let _ = writeln!(block, "{stmt}");
        }
        let _ = writeln!(block, "{inner_pad}{out_var} = _wf_some({decoded});");
        let _ = writeln!(block, "{pad}}} else {{");
        let _ = writeln!(
            block,
            "{inner_pad}throw new _wf_Error(\"InvalidState\", {{ message: {id} }});"
        );
        let _ = write!(block, "{pad}}}");
        stmts.push(block);
        Ok(out_var)
    }

    #[allow(clippy::too_many_arguments)]
    fn emit_decode_named_option_wrapper(
        &mut self,
        stmts: &mut Vec<String>,
        indent: usize,
        temps: &mut TempGen,
        expr: &str,
        target_glue: &str,
        plain_ty: &str,
        identity: &str,
    ) -> String {
        self.imports.use_error();
        self.imports.use_none();
        let pad = " ".repeat(indent);
        let inner_pad = " ".repeat(indent + 2);
        let id = escape_ts_string(identity);
        let out_var = temps.fresh();
        let wrap_var = temps.fresh();
        let mut block = format!("{pad}let {out_var}: {plain_ty};\n");
        let _ = writeln!(block, "{pad}const {wrap_var} = {expr};");
        let _ = writeln!(block, "{pad}if ({wrap_var}.value.case === \"none\") {{");
        let _ = writeln!(block, "{inner_pad}{out_var} = _wf_NONE;");
        let _ = writeln!(
            block,
            "{pad}}} else if ({wrap_var}.value.case === \"some\") {{"
        );
        let _ = writeln!(
            block,
            "{inner_pad}{out_var} = {target_glue}.fromProto({wrap_var}.value.value);"
        );
        let _ = writeln!(block, "{pad}}} else {{");
        let _ = writeln!(
            block,
            "{inner_pad}throw new _wf_Error(\"InvalidState\", {{ message: {id} }});"
        );
        let _ = write!(block, "{pad}}}");
        stmts.push(block);
        out_var
    }

    fn emit_decode_inline_result(
        &mut self,
        stmts: &mut Vec<String>,
        indent: usize,
        temps: &mut TempGen,
        expr: &str,
        result: &ResultExpr,
        identity: &str,
    ) -> Result<String> {
        self.imports.use_error();
        let pad = " ".repeat(indent);
        let inner_pad = " ".repeat(indent + 2);
        let id = escape_ts_string(identity);
        let plain_res_ty = self.plain_type(&TypeExpr::Result(result.clone()))?;
        let out_var = temps.fresh();
        let wrap_var = temps.fresh();
        let mut block = format!("{pad}let {out_var}: {plain_res_ty};\n");
        let _ = writeln!(block, "{pad}const {wrap_var} = {expr};");
        let _ = writeln!(block, "{pad}if ({wrap_var}.value.case === \"ok\") {{");
        if let Some(ok_ty) = &result.ok {
            let mut ok_stmts = Vec::new();
            let decoded = self.emit_decode_singular(
                &mut ok_stmts,
                indent + 2,
                temps,
                &format!("{wrap_var}.value.value"),
                ok_ty,
                identity,
            )?;
            for stmt in ok_stmts {
                let _ = writeln!(block, "{stmt}");
            }
            let _ = writeln!(
                block,
                "{inner_pad}{out_var} = {{ tag: \"ok\", value: {decoded} }};"
            );
        } else {
            let _ = writeln!(block, "{inner_pad}{out_var} = {{ tag: \"ok\" }};");
        }
        let _ = writeln!(
            block,
            "{pad}}} else if ({wrap_var}.value.case === \"err\") {{"
        );
        if let Some(err_ty) = &result.err {
            let mut err_stmts = Vec::new();
            let decoded = self.emit_decode_singular(
                &mut err_stmts,
                indent + 2,
                temps,
                &format!("{wrap_var}.value.value"),
                err_ty,
                identity,
            )?;
            for stmt in err_stmts {
                let _ = writeln!(block, "{stmt}");
            }
            let _ = writeln!(
                block,
                "{inner_pad}{out_var} = {{ tag: \"err\", error: {decoded} }};"
            );
        } else {
            let _ = writeln!(block, "{inner_pad}{out_var} = {{ tag: \"err\" }};");
        }
        let _ = writeln!(block, "{pad}}} else {{");
        let _ = writeln!(
            block,
            "{inner_pad}throw new _wf_Error(\"UnknownCase\", {{ message: {id} }});"
        );
        let _ = write!(block, "{pad}}}");
        stmts.push(block);
        Ok(out_var)
    }

    // --- Structural unwrapping helpers for named option<list|map|option> ---

    fn list_info(&self, ty: &TypeExpr) -> Result<(TypeExpr, Option<u32>)> {
        self.list_info_in(None, ty)
    }

    fn list_info_in(
        &self,
        context: Option<&'a Dependency>,
        ty: &TypeExpr,
    ) -> Result<(TypeExpr, Option<u32>)> {
        match ty {
            TypeExpr::List(element) => Ok((qualify_type(context, element), None)),
            TypeExpr::FixedLengthList(element, len) => {
                Ok((qualify_type(context, element), Some(*len)))
            }
            TypeExpr::Named(name) => {
                let (dep, def) = self.resolve_type_def(context, name)?;
                match &def.kind {
                    TypeDefKind::List(element) => Ok((qualify_type(dep, element), None)),
                    TypeDefKind::FixedLengthList(element, len) => {
                        Ok((qualify_type(dep, element), Some(*len)))
                    }
                    TypeDefKind::Alias(target) => self.list_info_in(dep, target),
                    _ => bail!("type `{name}` is not a list"),
                }
            }
            _ => bail!("type is not a list"),
        }
    }

    fn map_types(&self, ty: &TypeExpr) -> Result<(TypeExpr, TypeExpr)> {
        self.map_types_in(None, ty)
    }

    fn map_types_in(
        &self,
        context: Option<&'a Dependency>,
        ty: &TypeExpr,
    ) -> Result<(TypeExpr, TypeExpr)> {
        match ty {
            TypeExpr::Map(k, v) => Ok((qualify_type(context, k), qualify_type(context, v))),
            TypeExpr::Named(name) => {
                let (dep, def) = self.resolve_type_def(context, name)?;
                match &def.kind {
                    TypeDefKind::Map(k, v) => Ok((qualify_type(dep, k), qualify_type(dep, v))),
                    TypeDefKind::Alias(target) => self.map_types_in(dep, target),
                    _ => bail!("type `{name}` is not a map"),
                }
            }
            _ => bail!("type is not a map"),
        }
    }

    fn option_payload(&self, ty: &TypeExpr) -> Result<TypeExpr> {
        self.option_payload_in(None, ty)
    }

    fn option_payload_in(
        &self,
        context: Option<&'a Dependency>,
        ty: &TypeExpr,
    ) -> Result<TypeExpr> {
        match ty {
            TypeExpr::Option(payload) => Ok(qualify_type(context, payload)),
            TypeExpr::Named(name) => {
                let (dep, def) = self.resolve_type_def(context, name)?;
                match &def.kind {
                    TypeDefKind::Option(payload) => Ok(qualify_type(dep, payload)),
                    TypeDefKind::Alias(target) => self.option_payload_in(dep, target),
                    _ => bail!("type `{name}` is not an option"),
                }
            }
            _ => bail!("type is not an option"),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn import_root_validation_and_resolution_handle_relative_and_package_specifiers() {
        for valid in [
            ".",
            "..",
            "./plain",
            "../plain",
            "../../gen/proto-es",
            "@acme/contracts-plain",
            "@acme/contracts/gen/proto",
            "acme-contracts",
            "acme_contracts/sub-dir",
        ] {
            validate_import_root(valid).unwrap_or_else(|e| panic!("should accept `{valid}`: {e}"));
        }
        for invalid in [
            "",
            "   ",
            "../plain/",
            "/abs/path",
            "C:/win/path",
            "../plain\\sub",
            "../plain//sub",
            "../has space",
            "../has\"quote",
            "../has;semi",
            "@scope-only",
            "@/pkg",
            "@scope/..",
            "pkg/../escape",
            "https://example.com/pkg",
        ] {
            assert!(
                validate_import_root(invalid).is_err(),
                "must reject `{invalid}`"
            );
        }

        assert_eq!(
            resolve_import("../plain", 1, "v0_1/types.js"),
            "../../plain/v0_1/types.js"
        );
        assert_eq!(
            resolve_import("../proto", 2, "witforge.conformance_dep.v0_pb.js"),
            "../../../proto/witforge.conformance_dep.v0_pb.js"
        );
        assert_eq!(
            resolve_import("./sub/plain", 1, "v0_1/types.js"),
            "../sub/plain/v0_1/types.js"
        );
        assert_eq!(
            resolve_import("@acme/plain", 3, "witforge_deps/v0/ns_pkg/types.js"),
            "@acme/plain/witforge_deps/v0/ns_pkg/types.js"
        );
    }

    #[test]
    fn protobuf_es_naming_matches_bufbuild_v2_rules() {
        for pair in ES_RESERVED_IDENTIFIERS.windows(2) {
            assert!(
                pair[0] < pair[1],
                "ES_RESERVED_IDENTIFIERS unsorted: {pair:?}"
            );
        }
        assert_eq!(es_field_local_name("a-u8"), "aU8");
        assert_eq!(es_field_local_name("foo-BAR"), "fooBAR");
        assert_eq!(es_field_local_name("foo-1a"), "foo1a");
        assert_eq!(es_field_local_name("constructor"), "constructor$");
        assert_eq!(es_field_local_name("to-string"), "toString$");
        assert_eq!(es_oneof_case_local_name("constructor"), "constructor");
        assert_eq!(es_oneof_case_local_name("to-string"), "toString");
        assert_eq!(es_oneof_case_local_name("unit-case"), "unitCase");

        // Schema collision salting (`TypesFoo` + `TypesFooSchema` -> `TypesFooSchema$` for Foo's desc)
        let sample_proto = r#"syntax = "proto3";
package ex.t.v0;
message Empty {}
message TypesFoo { optional uint32 id = 1; }
message TypesFooSchema { optional uint32 id = 1; }
enum AMethod {
  AMETHOD_UNSPECIFIED = 0;
  A_METHOD_PING = 1;
}
enum ApiMethod {
  API_METHOD_UNSPECIFIED = 0;
  API_METHOD_ECHO_INTEGERS = 1;
}
"#;
        let parsed = EsFileNames::parse("v0.proto", sample_proto);
        assert_eq!(parsed.shape("TypesFoo"), "TypesFoo");
        assert_eq!(parsed.shape("TypesFooSchema"), "TypesFooSchema");
        assert_eq!(parsed.desc("TypesFoo"), "TypesFooSchema$");
        assert_eq!(parsed.desc("TypesFooSchema"), "TypesFooSchemaSchema");
        // `AMethod`: `AMETHOD_UNSPECIFIED` does not start with `a_method_` -> unstripped!
        assert_eq!(
            parsed.enum_member("AMethod", "A_METHOD_PING"),
            "A_METHOD_PING"
        );
        // `ApiMethod`: all values start with `api_method_` -> stripped!
        assert_eq!(
            parsed.enum_member("ApiMethod", "API_METHOD_ECHO_INTEGERS"),
            "ECHO_INTEGERS"
        );
    }
}
